const errors={invalid_department:['Enter your département number, for example 75, 93 or 2A.','Saisissez le numéro de votre département, par exemple 75, 93 ou 2A.'],invalid_height:['Height must be between 120 and 230 cm.','La taille doit être comprise entre 120 et 230 cm.'],invalid_reason:['Choose a reason.','Choisissez une raison.'],interest_consent_required:['Tick the consent box to use « Who would you like to see? », or leave it on « Everyone ».','Cochez la case de consentement pour utiliser « Qui souhaitez-vous voir ? », ou laissez « Tout le monde ».'],invalid_interest:['Choose women, men or everyone.','Choisissez femmes, hommes ou tout le monde.'],validation_failed:['This email address looks incomplete (example: name@yahoo.fr). Please check it.','Cette adresse e-mail semble incomplète (exemple : nom@yahoo.fr). Vérifiez-la.'],'Unable to validate email address':['This email address looks incomplete (example: name@yahoo.fr). Please check it.','Cette adresse e-mail semble incomplète (exemple : nom@yahoo.fr). Vérifiez-la.'],rules_required:['Please accept the community rules to continue.','Acceptez les règles de communauté pour continuer.'],unsupported_language:['Choose French or English.','Choisissez le français ou l’anglais.'],invalid_invitation:['This invitation has expired or is unavailable. Ask the venue for a current QR code.','Cette invitation a expiré ou est indisponible. Demandez un QR code valide au lieu.'],not_co_present:['This person is not available in your place right now.','Cette personne n’est pas disponible dans votre lieu pour le moment.'],introduction_exists:['You already introduced yourself to this person. Please respect their choice: they can write to you if they wish.','Vous vous êtes déjà présenté·e à cette personne. Respectez son choix : elle pourra vous écrire si elle le souhaite.'],introduction_received:['This person already wrote to you: answer from your messages.','Cette personne vous a déjà écrit : répondez depuis vos messages.'],introduction_limit:['You have reached the limit of introductions for this visit.','Vous avez atteint la limite de présentations pour cette visite.'],introduction_unavailable:['This introduction is no longer available.','Cette présentation n’est plus disponible.'],reply_required:['Write a reply to accept.','Écrivez une réponse pour accepter.'],message_length:['Your message must be between 1 and 2000 characters.','Votre message doit faire entre 1 et 2000 caractères.'],conversation_unavailable:['This conversation is not available.','Cette conversation n’est pas disponible.'],conversation_closed:['This conversation is closed.','Cette conversation est terminée.'],invalid_category:['Choose a reason.','Choisissez un motif.'],report_limit:['Too many reports today.','Trop de signalements aujourd’hui.'],meeting_too_early:['Exchange a few messages first.','Échangez d’abord quelques messages.'],no_live_session:['Join a place first to see who is there.','Rejoignez d’abord un lieu pour voir qui est présent.'],profile_required:['Complete your profile (photo and bio included) before joining a place.','Complétez votre profil (photo et présentation comprises) avant de rejoindre un lieu.'],bio_length:['Your bio must be between 1 and 300 characters.','Votre présentation doit faire entre 1 et 300 caractères.'],photo_missing:['Please add a profile photo.','Ajoutez une photo de profil.'],name_length:['Your display name must be 2 to 40 characters.','Votre nom affiché doit faire entre 2 et 40 caractères.'],adults_only:[`${BRAND.name} is for adults aged 18 and over. Check your birth date.`,`${BRAND.name} est réservé aux personnes de 18 ans et plus. Vérifiez votre date de naissance.`],birth_date_locked:['Your birth date cannot be changed here.','Votre date de naissance ne peut pas être modifiée ici.'],account_restricted:['Your account is restricted.','Votre compte est restreint.'],verified_account_required:['Please confirm your email before continuing.','Confirmez votre adresse e-mail avant de continuer.'],type_locked:['A venue account cannot become a personal account (or the reverse). Create a separate account.','Un compte établissement ne peut pas devenir un compte personnel (ni l’inverse). Créez un compte distinct.'],venue_account_required:['This action is for venue accounts.','Cette action est réservée aux comptes établissement.'],application_pending:['Your application is already being reviewed.','Votre demande est déjà en cours d’examen.'],venue_required:['Your venue is not approved yet.','Votre établissement n’est pas encore approuvé.'],invalid_duration:['Choose a duration between 15 minutes and 3 hours.','Choisissez une durée entre 15 minutes et 3 heures.'],pro_account_required:['This action is for professional accounts.','Cette action est réservée aux comptes professionnels.'],pro_not_approved:['Your professional sheet must be approved first.','Votre fiche professionnelle doit d’abord être approuvée.'],pass_required:['A pass for this place is needed for that (simulated during the test).','Un pass pour ce lieu est nécessaire pour cela (simulé pendant le test).'],simulation_only:['Simulated purchases are off.','Les achats simulés sont désactivés.'],invalid_score:['Pick a face first.','Choisissez d’abord un visage.'],venue_account:['Venue accounts manage their place; they do not take part in encounters.','Les comptes établissement gèrent leur lieu ; ils ne participent pas aux rencontres.'],invalid_type:['Choose an account type.','Choisissez un type de compte.'],not_configured:['Translation is not available yet in this test.','La traduction n’est pas encore disponible dans ce test.'],translation_failed:['Translation failed. Try again later.','La traduction a échoué. Réessayez plus tard.'],visit_over:['You are no longer in the same place. The conversation stays readable; it continues when you are both checked in there again.','Vous n’êtes plus dans le même lieu. La conversation reste lisible ; elle reprend quand vous y êtes de nouveau tous les deux.']};
function friendly(error){const entry=Object.entries(errors).find(([key])=>error.message?.includes(key));if(entry)return T(...entry[1]);if(error.code==='email_not_confirmed')return T('Confirm your email first. You can request a new confirmation below.','Confirmez votre e-mail. Vous pouvez demander une nouvelle confirmation ci-dessous.');if(error.code==='invalid_credentials')return T('Email or password is incorrect.','Adresse e-mail ou mot de passe incorrect.');if(error.code==='email_address_not_authorized'||error.message?.includes('Email address not authorized'))return T('Email delivery is not enabled for this address yet. The test administrator must finish the email setup.','L’envoi d’e-mails n’est pas encore activé pour cette adresse. L’administrateur doit terminer la configuration.');if(error.status===429)return T('Too many attempts. Please wait before trying again.','Trop de tentatives. Patientez avant de réessayer.');if((error.smsStep||/sms|hook/i.test(error.message||''))&&(error.status>=500||/sms_failed|not_configured|invalid_signature|hook|sms/i.test(error.message||'')))return T('The SMS code could not be sent. The test administrator must check the SMS settings. Meanwhile, sign in with your email.','Le code SMS n’a pas pu être envoyé. L’administrateur du test doit vérifier la configuration des SMS. En attendant, connectez-vous avec votre e-mail.');if(/sending .*e-?mail|smtp/i.test(error.message||'')||error.code==='email_send_failed')return T('Your account request reached the server, but the confirmation email could not be sent. The test administrator must check the email settings (SMTP). Try again later.','Votre demande est arrivée au serveur, mais l’e-mail de confirmation n’a pas pu être envoyé. L’administrateur du test doit vérifier la configuration des e-mails (SMTP). Réessayez plus tard.');const ref=[error.code,error.status].filter(Boolean).join(' ');return T('The request could not be completed. Check your connection and try again.','La demande n’a pas abouti. Vérifiez votre connexion puis réessayez.')+(ref?` (${ref})`:'');}
function age(date){const d=new Date(date);if(Number.isNaN(d.getTime()))return null;const now=new Date();let a=now.getFullYear()-d.getFullYear();if(now.getMonth()<d.getMonth()||(now.getMonth()===d.getMonth()&&now.getDate()<d.getDate()))a--;return a;}
function complete(p){if(!p)return false;if(p.account_type==='venue')return !!(p.display_name&&p.locale);return !!(p.display_name&&p.birth_date&&p.locale&&p.bio&&p.avatar_path);}
