async function prepareImage(file){if(!file||!file.type.startsWith('image/'))throw Object.assign(new Error('photo_missing'),{code:'photo_missing'});if(file.size>12*1024*1024)throw new Error('photo_missing');const bitmap=await createImageBitmap(file);const max=640,scale=Math.min(1,max/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close?.();return new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(new Error('photo_missing')),'image/jpeg',0.85));}
async function uploadPhoto(file){const blob=await prepareImage(file);const path=`u/${user.id}/avatar-${Date.now()}.jpg`;const {error}=await client.storage.from('avatars').upload(path,blob,{contentType:'image/jpeg',upsert:false});if(error)throw error;return path;}
async function loadAvatar(){avatarUrl='';if(!profile?.avatar_path)return;const {data}=await client.storage.from('avatars').createSignedUrl(profile.avatar_path,3600);avatarUrl=data?.signedUrl||'';}
async function removeOldPhoto(oldPath,newPath){if(oldPath&&oldPath!==newPath)await client.storage.from('avatars').remove([oldPath]).catch(()=>{});}
function photoField(required){const src=photoPreview||avatarUrl;return `<label for="photo">${T('Profile photo','Photo de profil')}</label>${src?`<img class="photo-preview" src="${esc(src)}" alt="">`:`<div class="photo-preview empty">${T('No photo yet','Pas encore de photo')}</div>`}<input id="photo" name="photo" type="file" accept="image/*" ${required?'required':''}><small>${T('A photo of you that other members in the same place will see. It is resized on your phone before sending; no selfie is ever required at check-in.','Une photo de vous, visible par les membres présents dans le même lieu. Elle est réduite sur votre téléphone avant l’envoi ; aucun selfie n’est jamais demandé à l’entrée.')}</small>`;}
const EYE='<svg viewBox="0 0 24 24" width="22" height="22" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M2 12s3.6-7 10-7 10 7 10 7-3.6 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/></svg>',EYE_OFF='<svg viewBox="0 0 24 24" width="22" height="22" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M10.6 5.1A10.8 10.8 0 0 1 12 5c6.4 0 10 7 10 7a17.6 17.6 0 0 1-3.2 4.2M6.6 6.6C3.7 8.4 2 12 2 12s3.6 7 10 7a9.7 9.7 0 0 0 5.4-1.6"/><path d="M9.9 9.9a3 3 0 0 0 4.2 4.2"/><path d="M2 2l20 20"/></svg>';
function field(label,name,type='text',value='',extra=''){const input=`<input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}>`;if(type!=='password')return `<label for="${name}">${label}</label>${input}`;
  // Password fields: an eye button shows or hides the text; on new passwords, a button suggests a strong one
  // (the browser's own password manager can also propose and save one thanks to autocomplete="new-password").
  return `<label for="${name}">${label}</label><div class="pw-wrap">${input}<button type="button" class="pw-eye" data-pw-toggle="${name}" aria-controls="${name}" aria-pressed="false" aria-label="${T('Show password','Afficher le mot de passe')}">${EYE}</button></div>${/new-password/.test(extra)?`<button type="button" class="link pw-suggest" data-pw-suggest="${name}">${T('Suggest a strong password','Suggérer un mot de passe sûr')}</button>`:''}`;}
// Strong password from the browser's cryptographic generator: 16 characters, no look-alike characters, at least one
// lowercase letter, uppercase letter, digit and symbol. Never sent anywhere except to Supabase Auth on submit.
function strongPassword(len=16){const sets=['abcdefghijkmnopqrstuvwxyz','ABCDEFGHJKLMNPQRSTUVWXYZ','23456789','!#$%&*+-=?@_'];const all=sets.join('');
  const pick=set=>{const max=256-(256%set.length);const b=new Uint8Array(1);do{crypto.getRandomValues(b);}while(b[0]>=max);return set[b[0]%set.length];};
  const chars=sets.map(pick);while(chars.length<len)chars.push(pick(all));
  for(let i=chars.length-1;i>0;i--){const b=new Uint32Array(1);crypto.getRandomValues(b);const j=b[0]%(i+1);[chars[i],chars[j]]=[chars[j],chars[i]];}return chars.join('');}
function setPwVisible(name,visible){const input=document.getElementById(name),btn=document.querySelector(`[data-pw-toggle="${name}"]`);if(!input||!btn)return;input.type=visible?'text':'password';btn.setAttribute('aria-pressed',String(visible));btn.setAttribute('aria-label',visible?T('Hide password','Masquer le mot de passe'):T('Show password','Afficher le mot de passe'));btn.innerHTML=visible?EYE_OFF:EYE;}
document.addEventListener('click',e=>{const t=e.target.closest('[data-pw-toggle],[data-pw-suggest]');if(!t)return;e.preventDefault();
  if(t.dataset.pwToggle){const input=document.getElementById(t.dataset.pwToggle);setPwVisible(t.dataset.pwToggle,input?.type==='password');input?.focus();return;}
  const input=document.getElementById(t.dataset.pwSuggest);if(!input)return;input.value=strongPassword();setPwVisible(t.dataset.pwSuggest,true);input.dispatchEvent(new Event('input',{bubbles:true}));input.focus();
  notice(T('Strong password suggested. Save it in your password manager or note it somewhere safe before continuing.','Mot de passe sûr proposé. Enregistrez-le dans votre gestionnaire de mots de passe ou notez-le en lieu sûr avant de continuer.'));});
function langChips(){return `<div class="lang-choice" role="group" aria-label="Langue / Language"><button type="button" data-language="fr" aria-pressed="${lang==='fr'}">Français</button><button type="button" data-language="en" aria-pressed="${lang==='en'}">English</button></div>`;}
function landingView(){return `<div class="welcome-art" aria-hidden="true"><img src="./assets/maya.jpg" alt=""><span class="hello-bubble">${T('Hello, you.','Salut, vous.')}</span><img src="./assets/adam.jpg" alt=""></div><p class="eyebrow">${T('SAME PLACE. NEW CONNECTIONS.','UN MÊME LIEU. DE NOUVELLES RENCONTRES.')}</p><h2 id="card-title">${T('The first step<br>starts here.','Le premier pas<br>commence ici.')}</h2><p class="lead">${T('Meet people in your venue. A hello, a conversation. Always your choice.','Rencontrez les personnes de votre lieu. Un bonjour, une discussion. Toujours à votre rythme.')}</p><button class="button wide" data-mode="signup">${T('Get started','Commencer')} →</button><button class="button secondary wide" data-mode="signin">${T('I already have an account','J’ai déjà un compte')}</button><div class="journey-hint"><span>01 ${T('Scan','Scannez')}</span><span>02 ${T('Say hello','Dites bonjour')}</span><span>03 ${T('Connect','Échangez')}</span></div><details><summary>${T('Professional or venue?','Professionnel ou établissement ?')}</summary><p>${T('Choose your account type after registration. Professionals share their talent; venues manage their QR codes.','Choisissez votre type de compte après inscription. Les professionnels présentent leur talent ; les établissements gèrent leurs QR codes.')}</p><button class="link" data-mode="signup">${T('Create an account','Créer un compte')} →</button></details><p class="quiet">${T('18+ · No obligation to reply · Test version, no charges','18 ans et plus · Aucune obligation de répondre · Test sans paiement')}</p><p class="quiet"><a href="./confidentialite.html">${T('Privacy','Confidentialité')}</a> · <a href="./cgu.html">${T('Terms','Conditions')}</a></p>`;}

function providersBlock(){const pk=passkeyReady()&&mode==='signin'?`<button type="button" class="button wide" data-action="passkey-signin">🔑 ${T('Sign in with a passkey','Se connecter avec une clé d’accès')}</button><p class="quiet">${T('Face ID, fingerprint or device PIN.','Face ID, empreinte ou code du téléphone.')}</p>`:'';const g=config.providers?.google?`<button type="button" class="button secondary wide" data-action="google">${T('Continue with Google','Continuer avec Google')}</button>`:'';const ph=config.providers?.phone?`<button type="button" class="button secondary wide" data-mode="phone">${T('Continue with my phone number','Continuer avec mon numéro de téléphone')}</button>`:'';return pk||g||ph?`<div class="providers">${pk}${g}${ph}</div>`:'';}
function phoneView(){return `<h2 id="card-title">${T('Sign in with your phone','Connexion par téléphone')}</h2>${phoneStep==='code'?`<form data-form="phone-code"><p class="quiet">${T('We sent a code by SMS to','Nous avons envoyé un code par SMS au')} ${esc(phoneValue)}.</p>${field(T('6-digit code','Code à 6 chiffres'),'code','text','','required inputmode="numeric" pattern="[0-9]{6}" autocomplete="one-time-code"')}<button class="button">${T('Confirm','Confirmer')}</button></form>`:`<form data-form="phone">${field(T('Mobile number (international format)','Numéro de mobile (format international)'),'phone','tel','+33','required autocomplete="tel" pattern="\\+[0-9]{8,15}"')}<small>${T('Example: +33612345678. Standard SMS rates may apply.','Exemple : +33612345678. Tarif SMS habituel.')}</small><button class="button">${T('Send me a code','M’envoyer un code')}</button></form>`}<p class="quiet">${T('Already have an account with your email? Sign in with your email, then add your phone number in « My profile & settings »: both will open the same profile.','Vous avez déjà un compte avec votre e-mail ? Connectez-vous avec l’e-mail, puis ajoutez votre numéro dans « Mon profil et réglages » : les deux ouvriront le même profil.')}</p><button class="link" data-mode="signin">${T('Use my email instead','Utiliser mon e-mail à la place')}</button>`;}
function authView(){if(mode==='landing')return landingView();if(mode==='phone')return phoneView();return `<button class="link" data-mode="landing">← ${T('Back','Retour')}</button>${mode==='signup'?`<p class="eyebrow">${T('Step 1 of 2 · your account (then your profile: name, photo, age, a few words)','Étape 1 sur 2 · votre compte (ensuite votre profil : nom, photo, âge, quelques mots)')}</p>`:''}<h2 id="card-title">${T(`Your ${BRAND.name} space`,`Votre espace ${BRAND.name}`)}</h2><div class="tabs"><button data-mode="signin" aria-pressed="${mode==='signin'}">${T('Sign in','Connexion')}</button><button data-mode="signup" aria-pressed="${mode==='signup'}">${T('Create account','Créer un compte')}</button></div>${providersBlock()}<details class="email-method" ${mode==='signup'||!config.providers?.phone?'open':''}><summary>${T('Continue with email','Continuer avec mon e-mail')}</summary><form data-form="auth">${field('E-mail','email','email','', 'required autocomplete="email" maxlength="254"')}${field(T('Password','Mot de passe'),'password','password','',`required minlength="${mode==='signup'?12:1}" autocomplete="${mode==='signup'?'new-password':'current-password'}"`)}${mode==='signup'?`<small>${T('At least 12 characters. Use a unique password.','Au moins 12 caractères. Utilisez un mot de passe unique.')}</small><p class="quiet">${T('Adults only. Confirm your email, then complete your private profile. No selfie required.','Réservé aux adultes. Confirmez votre e-mail puis complétez votre profil privé. Aucun selfie requis.')} ${T('By creating an account you accept the','En créant un compte, vous acceptez les')} <a href="./cgu.html">${T('terms of use','conditions d’utilisation')}</a> ${T('and the','et la')} <a href="./confidentialite.html">${T('privacy policy','politique de confidentialité')}</a>.</p>`:''}<button class="button" type="submit">${mode==='signup'?T('Create my account','Créer mon compte'):T('Sign in','Se connecter')}</button></form><button class="link" data-action="reset">${T('Forgot password?','Mot de passe oublié ?')}</button><button class="link" data-action="resend">${T('Resend confirmation','Renvoyer la confirmation')}</button></details><details><summary>${T('About this test','À propos de ce test')}</summary><p class="quiet">${T('Accounts and profiles are stored in the project’s dedicated database. Your birth date is private. Payments are simulated: nothing is ever charged during the test. Use test details during this pilot.','Les comptes et profils sont enregistrés dans la base dédiée au projet. Votre date de naissance reste privée. Les paiements sont simulés : rien n’est jamais débité pendant le test. Utilisez des données de test pendant ce pilote.')}</p></details>`;}
function typeView(){const opt=(k,title,desc)=>`<button class="choice" data-type="${k}"><b>${title}</b><span>${desc}</span></button>`;return `${langChips()}<h2 id="card-title">${T('I am here as…','Je suis ici en tant que…')}</h2><p class="quiet">${T('Choose once. Venue accounts manage a place and never take part in encounters.','Choisissez une fois. Les comptes établissement gèrent un lieu et ne participent jamais aux rencontres.')}</p><div class="choices">${opt('personal',T('A person','Une personne'),T('Meet people present in the same place, with consent.','Rencontrer des personnes présentes dans le même lieu, avec consentement.'))}${opt('pro',T('A professional','Un·e professionnel·le'),T('Everything a person can do, plus a professional sheet visible to people in the same place (DJ, artist, barber, photographer…).','Tout ce qu’une personne peut faire, plus une fiche professionnelle visible par les personnes du même lieu (DJ, artiste, barbier, photographe…).'))}${opt('venue',T('A venue','Un établissement'),T('Restaurant, bar, shisha lounge, club, salon… Get your QR code, see how many people are checked in, post announcements.','Restaurant, bar, chicha, club, salon… Obtenez votre QR code, suivez les présences, publiez des annonces.'))}</div><button data-action="signout" class="link">${T('Sign out','Se déconnecter')}</button>`;}
function venueProfileView(){const p=profile||{};return `<h2 id="card-title">${T('Your venue account','Votre compte établissement')}</h2><p>${T('First, name the account. Then describe your place so the team can approve it.','D’abord, nommez le compte. Ensuite, décrivez votre lieu pour que l’équipe l’approuve.')}</p><form data-form="profile"><input type="hidden" name="venue" value="1">${field(T('Account name (your venue)','Nom du compte (votre établissement)'),'displayName','text',p.display_name||'','required minlength="2" maxlength="40" autocomplete="organization"')}<label for="locale">${T('Language','Langue')}</label><select name="locale" id="locale"><option value="fr" ${lang==='fr'?'selected':''}>Français</option><option value="en" ${lang==='en'?'selected':''}>English</option></select><div class="notice">${T('Venue accounts see counts and announcements only: never members’ profiles or messages.','Les comptes établissement voient des effectifs et des annonces uniquement : jamais les profils ni les messages des membres.')}</div><label class="agreement"><input name="rules" type="checkbox" required>${T('I accept the terms of use for partner venues.','J’accepte les conditions d’utilisation pour les établissements partenaires.')}</label><button class="button">${T('Continue','Continuer')}</button></form><button data-action="signout" class="link">${T('Sign out','Se déconnecter')}</button>`;}
const VENUE_CATS=()=>[['restaurant',T('Restaurant','Restaurant')],['pub',T('Bar / pub','Bar / pub')],['chicha',T('Shisha lounge','Chicha')],['nightclub',T('Club','Discothèque')],['barber',T('Barber / salon','Barbier / salon')],['test',T('Test venue','Lieu de test')]];
function durationOptions(cur){return [15,30,45,60,90,120,150,180].filter(m=>m<=maxMin()).map(m=>`<option value="${m}" ${Number(cur)===m?'selected':''}>${m<60?m+' min':(m/60)+' h'+(m%60?' '+(m%60):'')}</option>`).join('');}
function venueApplyView(app){if(app?.status==='pending')return `<div class="card"><span class="badge">${T('Under review','En cours d’examen')}</span><h3>${esc(app.venue_name)}</h3><p>${T('Thanks! The team checks each venue before activating it. You will see your dashboard here once approved.','Merci ! L’équipe vérifie chaque établissement avant de l’activer. Votre tableau de bord apparaîtra ici après approbation.')}</p><p class="quiet">${T('Sent on','Envoyée le')} ${esc(when(app.created_at))}</p></div>`;const rejected=app?.status==='rejected';return `${rejected?`<div class="notice">${T('Your previous application was not accepted.','Votre précédente demande n’a pas été acceptée.')} ${app.decision?esc(app.decision):''}</div>`:''}<h3>${T('Describe your venue','Décrivez votre établissement')}</h3><form data-form="apply">${field(T('Venue name','Nom de l’établissement'),'name','text',app?.venue_name||profile.display_name||'','required minlength="2" maxlength="100"')}<label for="category">${T('Type','Type')}</label><select id="category" name="category">${VENUE_CATS().map(([k,l])=>`<option value="${k}">${l}</option>`).join('')}</select>${field(T('Address','Adresse'),'address','text','','required minlength="5" maxlength="200" autocomplete="street-address"')}${field(T('Opening hours (optional)','Horaires (facultatif)'),'hours','text','','maxlength="300"')}${field(T('Contact for the team (phone or email, optional)','Contact pour l’équipe (téléphone ou e-mail, facultatif)'),'contact','text','','maxlength="120"')}<label for="duration">${T('Session length for visitors','Durée de session des visiteurs')}</label><select id="duration" name="duration">${durationOptions(60)}</select><small>${T(`During the test, sessions last at most ${maxMin()/60} hours.`,`Pendant le test, une session dure au maximum ${maxMin()/60} heures.`)}</small><button class="button">${T('Send my application','Envoyer ma demande')}</button></form>`;}
function venueHomeView(){const d=venueData||{};const v=d.venue;if(!v)return `<div class="me"><div><h2 id="card-title">${esc(profile.display_name)}</h2><p class="quiet">${T('Venue account','Compte établissement')}</p></div></div>${venueApplyView(d.application)}<div class="row"><button data-view="venue-settings" class="button secondary">${T('Account & settings','Compte et réglages')}</button><button data-view="help" class="button secondary">${T('Help','Aide')}</button></div><button data-action="signout" class="button secondary">${T('Sign out','Se déconnecter')}</button>`;const tile=(n,l)=>`<div class="tile"><b>${esc(n??'—')}</b><span>${l}</span></div>`;return `<div class="me"><div><h2 id="card-title">${esc(v.name)}</h2><p class="quiet">${esc(v.address||'')}${v.active?'':' · '+T('inactive','inactif')}</p></div></div><div class="tiles">${tile(v.present,T('checked in now','présents maintenant'))}${tile(v.today,T('check-ins / 24 h','entrées / 24 h'))}${tile(v.open_reports,T('open reports','signalements ouverts'))}</div><h3>${T('QR code & invitations','QR code et invitations')}</h3><p class="quiet">${T('Print the QR code at the entrance. Visitors scan it with UPZONE to join your place for one session.','Imprimez le QR code à l’entrée. Les visiteurs le scannent avec UPZONE pour rejoindre votre lieu le temps d’une session.')}</p>${(v.invites||[]).map(i=>`<div class="item"><div class="head"><b>${T('Valid until','Valide jusqu’au')} ${esc(when(i.expires_at))}</b><span class="right">${esc(i.uses)} ${T('check-in(s)','entrée(s)')}</span></div>${venueQr[i.id]?`<img class="qr" alt="QR code" src="${esc(venueQr[i.id].qr)}" width="220" height="220"><input readonly value="${esc(venueQr[i.id].url)}" onclick="this.select()"><a class="button secondary" download="prod-qr-${esc(v.name).replace(/[^a-z0-9]+/gi,'-').toLowerCase()}.png" href="${esc(venueQr[i.id].qr)}">${T('Download the QR code','Télécharger le QR code')}</a>`:`<p class="quiet">${T('QR code shown once at creation. Create a new one if you lost it.','QR code affiché une seule fois à la création. Créez-en un nouveau si vous l’avez perdu.')}</p>`}<button class="link" data-action="venue-revoke" data-id="${esc(i.id)}">${T('Revoke (ends current sessions)','Révoquer (termine les sessions en cours)')}</button></div>`).join('')}<form data-form="venue-invite" class="row"><select name="days"><option value="7">${T('Valid 7 days','Valable 7 jours')}</option><option value="30">${T('Valid 30 days','Valable 30 jours')}</option><option value="90" selected>${T('Valid 90 days','Valable 90 jours')}</option></select><button class="button">${T('New QR code','Nouveau QR code')}</button></form><h3>${T('Announcements','Annonces')}</h3><p class="quiet">${T('Shown to people checked in (12 hours): happy hour, event, special offer.','Affichées aux personnes présentes (12 heures) : happy hour, événement, offre.')}</p>${(v.announcements||[]).map(a=>`<p class="bubble">${esc(a.body)}<br><small>${esc(when(a.created_at))} · <button class="link" data-action="venue-unannounce" data-id="${esc(a.id)}">${T('Remove','Retirer')}</button></small></p>`).join('')}<form data-form="venue-announce"><textarea name="body" required maxlength="300" rows="2" placeholder="${T('Your announcement…','Votre annonce…')}"></textarea><button class="button secondary">${T('Publish','Publier')}</button></form><details><summary>${T('Venue settings','Réglages du lieu')}</summary><form data-form="venue-update">${field(T('Opening hours','Horaires'),'hours','text',v.hours||'','maxlength="300"')}${field(T('Contact for the team','Contact pour l’équipe'),'contact','text',v.contact||'','maxlength="120"')}<label for="duration">${T('Session length','Durée de session')}</label><select id="duration" name="duration">${durationOptions(v.duration_minutes)}</select><button class="button secondary">${T('Save','Enregistrer')}</button></form></details><div class="row"><button data-view="venue-settings" class="button secondary">${T('Account & settings','Compte et réglages')}</button><button data-view="help" class="button secondary">${T('Help','Aide')}</button></div>${isAdmin?`<a href="./admin.html">${T('Administration','Administration')}</a>`:''}<button data-action="signout" class="button secondary">${T('Sign out','Se déconnecter')}</button>`;}
function venueSettingsView(){return `<button class="link" data-view="home">← ${T('Back','Retour')}</button><h2 id="card-title">${T('Account & settings','Compte et réglages')}</h2><form data-form="settings"><input type="hidden" name="venue" value="1">${field(T('Account name','Nom du compte'),'displayName','text',profile.display_name,'required minlength="2" maxlength="40"')}<label for="locale">${T('Language','Langue')}</label><select name="locale" id="locale"><option value="fr" ${profile.locale==='fr'?'selected':''}>Français</option><option value="en" ${profile.locale==='en'?'selected':''}>English</option></select><p class="quiet">${T('Account email','E-mail du compte')} : ${esc(user.email||user.phone||'')}</p><button class="button">${T('Save','Enregistrer')}</button></form><button data-action="feedback" class="button secondary">${T('Give feedback on the test','Donner mon avis sur le test')}</button><p class="quiet"><a href="./confidentialite.html">${T('Privacy policy','Politique de confidentialité')}</a> · <a href="./cgu.html">${T('Terms of use','Conditions d’utilisation')}</a></p><h3>${T('Delete my account','Supprimer mon compte')}</h3><button data-action="delete" class="button secondary">${T('Delete my account','Supprimer mon compte')}</button>`;}
const PRO_CATS=()=>[T('DJ','DJ'),T('Musician / singer','Musicien·ne / chanteur·se'),T('Photographer / video','Photographe / vidéo'),T('Barber / hairdresser','Barbier / coiffeur·se'),T('Beauty / nails','Beauté / ongles'),T('Artist / performer','Artiste / performer'),T('Coach / trainer','Coach'),T('Event organiser','Organisateur·rice d’événements'),T('Other','Autre')];
function proSheetView(back){const d=proData||{};const soc=d.socials||{};return `${back?`<button class="link" data-view="pro">← ${T('Back','Retour')}</button>`:''}<h2 id="card-title">${d.business_name?T('My professional sheet','Ma fiche professionnelle'):T('Your professional sheet','Votre fiche professionnelle')}</h2><p class="quiet">${T('Visible only to people checked in the same place as you, once approved by the team. Your personal profile stays separate.','Visible uniquement par les personnes présentes dans le même lieu que vous, après approbation par l’équipe. Votre profil personnel reste séparé.')}</p><form data-form="pro">${field(T('Business or brand name','Nom de l’activité ou de la marque'),'business','text',d.business_name||'','required minlength="2" maxlength="100" autocomplete="organization"')}${field(T('Professional name (optional)','Nom professionnel (facultatif)'),'professional','text',d.professional_name||'','maxlength="80"')}<label for="category">${T('Category','Catégorie')}</label><input id="category" name="category" list="pro-cats" required minlength="2" maxlength="60" value="${esc(d.category||'')}"><datalist id="pro-cats">${PRO_CATS().map(c=>`<option value="${esc(c)}">`).join('')}</datalist><label for="pitch">${T('Your pitch','Votre présentation')}</label><textarea id="pitch" name="pitch" required minlength="10" maxlength="600" rows="4">${esc(d.pitch||'')}</textarea><small>${T('10 to 600 characters: what you do, for whom, how to book.','10 à 600 caractères : ce que vous faites, pour qui, comment réserver.')}</small>${field(T('Website (optional)','Site web (facultatif)'),'website','url',d.website||'','placeholder="https://" maxlength="200"')}${field('Instagram','instagram','text',soc.instagram||'','maxlength="120" placeholder="@"')}${field('TikTok','tiktok','text',soc.tiktok||'','maxlength="120" placeholder="@"')}${field('LinkedIn','linkedin','text',soc.linkedin||'','maxlength="120"')}${field(T('City / area','Ville / secteur'),'city','text',d.city||'','maxlength="80" autocomplete="address-level2"')}<button class="button">${d.business_name?T('Save','Enregistrer'):T('Send for approval','Envoyer pour approbation')}</button></form>${back?'':`<button class="link" data-action="skip-pro">${T('Later: continue as a person for now','Plus tard : continuer comme une personne pour l’instant')}</button>`}`;}
function proView(){const d=proData;if(!d)return proSheetView(false);const st=d.status;return `<button class="link" data-view="home">← ${T('Back','Retour')}</button><h2 id="card-title">${esc(d.business_name)}</h2><p class="quiet">${esc(d.category)}${d.city?' · '+esc(d.city):''}</p><span class="badge">${st==='approved'?T('Approved','Approuvée'):st==='rejected'?T('Not accepted','Refusée'):T('Under review','En cours d’examen')}</span>${st==='rejected'&&d.decision?`<p class="notice">${esc(d.decision)}</p>`:''}${st==='approved'?`<div class="card"><h3>${T('Talent subscription','Abonnement talent')} ${SIM()}</h3>${d.subscription_active?`<p>${T('Active until','Actif jusqu’au')} ${esc(when(d.subscription_until))}. ${T('Your sheet appears in “Talents here” for people checked in the same place.','Votre fiche apparaît dans « Talents ici » pour les personnes présentes dans le même lieu.')}</p>`:`<p>${T('Without a subscription your sheet is saved but not shown. During the test, subscriptions are simulated and free.','Sans abonnement, votre fiche est enregistrée mais pas affichée. Pendant le test, l’abonnement est simulé et gratuit.')}</p><button class="button" data-action="subscribe">${T('Activate 30 days (simulation)','Activer 30 jours (simulation)')}</button>`}</div>`:''}<h3>${T('Enquiries received','Demandes reçues')}</h3>${(d.enquiries||[]).length?d.enquiries.map(e=>`<div class="item"><div class="head"><b>${esc(e.from||'')}</b><span class="right">${esc(when(e.created_at))}${e.venue?' · '+esc(e.venue):''}</span></div><p class="bubble">${esc(e.message)}</p>${e.contact?`<p class="quiet">${T('Contact left','Contact laissé')} : ${esc(e.contact)}</p>`:''}</div>`).join(''):`<p class="quiet">${T('No enquiry yet.','Aucune demande pour l’instant.')}</p>`}<button class="button secondary" data-view="pro-edit">${T('Edit my sheet','Modifier ma fiche')}</button>`;}
function talentCard(t){return `<button class="person" data-talent="${esc(t.user_id)}"><img class="avatar" src="${esc(t.photo||'')}" alt="" loading="lazy"><span><b>${esc(t.business_name)}</b><small>${esc(t.category)}${t.professional_name?' · '+esc(t.professional_name):''}</small></span></button>`;}
function talentsView(){return `<button class="link" data-view="home">← ${T('Back','Retour')}</button><h2 id="card-title">${T('Talents here','Talents ici')}</h2><p class="quiet">${esc(session?.venue_name||'')} · ${T('professionals checked in this place right now','professionnel·le·s présent·e·s dans ce lieu en ce moment')}</p>${!talentsLoaded?`<p role="status">${T('Loading…','Chargement…')}</p>`:talents.length?`<div class="people">${talents.map(talentCard).join('')}</div>`:`<div class="notice">${T('No talent checked in right now.','Aucun talent présent pour le moment.')}</div>`}<button class="button secondary" data-action="talents">${T('Refresh','Actualiser')}</button>`;}
function talentView(){const t=talent;const soc=t.socials||{};const link=(l,v,h)=>v?`<li>${l} : ${h?`<a href="${esc(h)}" rel="noopener" target="_blank">${esc(v)}</a>`:esc(v)}</li>`:'';return `<button class="link" data-action="talents">← ${T('Back','Retour')}</button><div class="me"><img class="avatar" src="${esc(t.photo||'')}" alt=""><div><h2 id="card-title">${esc(t.business_name)}</h2><p class="quiet">${esc(t.category)}${t.professional_name?' · '+esc(t.professional_name):''}${t.city?' · '+esc(t.city):''}</p></div></div><p>${esc(t.pitch)}</p><ul class="quiet">${link(T('Website','Site'),t.website,t.website)}${link('Instagram',soc.instagram)}${link('TikTok',soc.tiktok)}${link('LinkedIn',soc.linkedin)}</ul><h3>${T('Send an enquiry','Envoyer une demande')}</h3><p class="quiet">${T('For bookings or questions. This is not a chat: the professional may answer with the contact you leave.','Pour une réservation ou une question. Ce n’est pas une messagerie : le·la professionnel·le pourra répondre au contact que vous laissez.')}</p><form data-form="enquiry" data-user="${esc(t.user_id)}"><textarea name="message" required minlength="1" maxlength="1000" rows="3" placeholder="${T('Your request…','Votre demande…')}"></textarea>${field(T('How to reach you (optional)','Comment vous joindre (facultatif)'),'contact','text','','maxlength="120"')}<button class="button">${T('Send','Envoyer')}</button></form><div class="row"><button class="link" data-action="block" data-user="${esc(t.user_id)}">${T('Block','Bloquer')}</button><button class="link" data-action="report" data-user="${esc(t.user_id)}">${T('Report','Signaler')}</button></div>`;}
function passBlock(){if(settings.pass_rule!=='everyone'||!live())return '';const active=passes.find(p=>p.kind==='venue_pass'&&p.active&&p.venue===session.venue_name);return `<div class="card pass"><h3>${T('Venue pass','Pass du lieu')} ${SIM()}</h3>${active?`<p>${T('Active until','Actif jusqu’à')} ${esc(hm(active.expires_at))}. ${T('You can read and answer accepted conversations in this place.','Vous pouvez lire et répondre aux conversations acceptées dans ce lieu.')}</p>`:`<p class="quiet">${T('A pass unlocks the replies of people who accepted your introduction, in this place and for this session. During the test it is simulated: one tap, nothing charged.','Un pass débloque les réponses des personnes qui ont accepté votre présentation, dans ce lieu et pour cette session. Pendant le test il est simulé : un geste, rien n’est débité.')}</p><button class="button" data-action="buy-pass">${T('Get my pass (simulation)','Obtenir mon pass (simulation)')}</button>`}</div>`;}
function roomBlock(){if(!room||!live())return '';return `<p class="quiet">${esc(room.present)} ${T('person(s) checked in here','personne(s) présente(s) ici')}</p>${(room.announcements||[]).map(a=>`<p class="bubble announce">📣 ${esc(a.body)}</p>`).join('')}`;}
function feedbackDialog(){return `<dialog id="feedback-dialog" class="feedback"><form data-form="feedback" method="dialog"><h3>${T('One hour with UPZONE: what do you think?','Une heure avec UPZONE : qu’en pensez-vous ?')}</h3><p class="quiet">${T('Two minutes. Your answers go to the test team.','Deux minutes. Vos réponses vont à l’équipe du test.')}</p><div class="faces" role="radiogroup" aria-label="${T('Score','Note')}">${[[1,'😕'],[2,'😐'],[3,'🙂'],[4,'🤩']].map(([v,f])=>`<label><input type="radio" name="score" value="${v}" required><span>${f}</span></label>`).join('')}</div><label for="fb-change">${T('What would you change first?','Que changeriez-vous en premier ?')}</label><textarea id="fb-change" name="change" maxlength="1000" rows="3"></textarea><label class="agreement"><input type="checkbox" name="bug">${T('I ran into a bug','J’ai rencontré un bug')}</label><textarea name="bugText" maxlength="1000" rows="2" placeholder="${T('What happened?','Que s’est-il passé ?')}"></textarea><div class="row"><button class="button" value="send">${T('Send','Envoyer')}</button><button class="button secondary" type="button" data-action="feedback-later">${T('Later','Plus tard')}</button></div></form></dialog>`;}
// « Who would you like to see? » Optional, private, explicit consent (with gender it reveals sexual orientation, GDPR art. 9).
// Only filters the member's own venue list on the server; never shown to anyone; never used for pricing.
function departmentField(value){return `<label for="department">${T('Département where you live','Département où vous habitez')}</label><input id="department" name="department" type="text" required minlength="2" maxlength="3" pattern="(0[1-9]|1[0-9]|2[1-9]|[3-8][0-9]|9[0-5]|2[AaBb]|97[1-6])" autocapitalize="characters" autocomplete="off" placeholder="93" value="${esc(value||'')}"><small>${T('Number only, for example 75, 93 or 2A. Shown to people in the same place.','Numéro seulement, par exemple 75, 93 ou 2A. Visible des personnes du même lieu.')}</small>`;}
function heightField(value){return `<label for="height">${T('Height · optional','Taille · facultatif')}</label><input id="height" name="height" type="number" inputmode="numeric" min="120" max="230" step="1" placeholder="175" value="${esc(value||'')}"><small>${T('In centimetres. Shown on your profile.','En centimètres. Affichée sur votre profil.')}</small>`;}
function interestField(value,consented){return `<label for="interest">${T('Who would you like to see? · optional','Qui souhaitez-vous voir ? · facultatif')}</label><select id="interest" name="interest">${[['',T('Everyone (no filter)','Tout le monde (sans filtre)')],['women',T('Women','Femmes')],['men',T('Men','Hommes')],['everyone',T('Mixed: women and men, and everyone','Mixte : femmes, hommes et tout le monde')]].map(([key,label])=>`<option value="${key}" ${value===key?'selected':''}>${label}</option>`).join('')}</select><label class="agreement"><input name="interestConsent" type="checkbox" ${consented?'checked':''}>${T('I agree that UPZONE uses this choice only to filter the people I see in a venue. It is private, never shown to anyone, and I can remove it at any time.','J’accepte qu’UPZONE utilise ce choix uniquement pour filtrer les personnes que je vois dans un lieu. Il est privé, jamais montré à personne, et je peux le retirer à tout moment.')}</label><small>${T('Women / Men show members who declared that gender. Leave it on « Everyone » to see everybody.','Femmes / Hommes affichent les membres ayant déclaré ce genre. Laissez « Tout le monde » pour voir tout le monde.')}</small>`;}
function genderField(value){return `<label for="gender">${T('Gender · optional','Genre · facultatif')}</label><select id="gender" name="gender" aria-describedby="gender-hint">${[['',T('Choose or leave blank','Choisir ou laisser vide')],['woman',T('Woman','Femme')],['man',T('Man','Homme')],['non_binary',T('Non-binary','Non-binaire')],['another_identity',T('Another identity','Autre identité')],['prefer_not_to_say',T('Prefer not to say','Je préfère ne pas répondre')]].map(([key,label])=>`<option value="${key}" ${value===key?'selected':''}>${label}</option>`).join('')}</select><small id="gender-hint">${T('Self-declared and private: not shown to other members. You can change or clear it in settings. It does not determine pricing in this pilot.','Déclaré par vous et privé : non affiché aux autres membres. Modifiable ou effaçable dans les réglages. Ne détermine pas les tarifs de ce pilote.')}</small>`;}
function profileView(){const p=profile||{};return `<p class="eyebrow">${T('Step 2 of 2 · your profile','Étape 2 sur 2 · votre profil')}</p><h2 id="card-title">${T('Make yourself at home','Bienvenue chez vous')}</h2><p>${T('Complete your profile before joining a place: name, photo, date of birth and a few words about you.','Complétez votre profil avant de rejoindre un lieu : nom, photo, date de naissance et quelques mots sur vous.')}</p><form data-form="profile">${field(T('Display name','Nom affiché'),'displayName','text',p.display_name||'', 'required minlength="2" maxlength="40" autocomplete="nickname"')}${photoField(!p.avatar_path)}${genderField(p.gender||'')}${interestField(p.interested_in||'',!!p.interest_consent_at)}${departmentField(p.department)}${heightField(p.height_cm)}${p.birth_date?`<label>${T('Date of birth · private','Date de naissance · privée')}</label><p class="quiet">${esc(p.birth_date)} · ${age(p.birth_date)} ${T('years old','ans')} · ${T('cannot be changed','non modifiable')}</p><input type="hidden" name="birthDate" value="${esc(p.birth_date)}">`:field(T('Date of birth · private','Date de naissance · privée'),'birthDate','date','', 'required autocomplete="bday"')}<small id="age-hint">${T('18+ only. Other members see your age, never your birth date. It cannot be edited after saving.','18 ans minimum. Les autres membres voient votre âge, jamais votre date de naissance. Non modifiable après enregistrement.')}</small><label for="bio">${T('About you','Quelques mots sur vous')}</label><textarea id="bio" name="bio" required minlength="1" maxlength="300" rows="3" placeholder="${T('What you like, what brings you here…','Ce que vous aimez, ce qui vous amène…')}">${esc(p.bio||'')}</textarea><small>${T('Up to 300 characters.','300 caractères maximum.')}</small><label for="locale">${T('Language','Langue')}</label><select name="locale" id="locale"><option value="fr" ${lang==='fr'?'selected':''}>Français</option><option value="en" ${lang==='en'?'selected':''}>English</option></select><div class="notice">${T('In a place, members who hold a pass for it see your profile. The others only see a neutral silhouette, your département and an age range (e.g. 26-30).','Dans un lieu, les membres qui ont un pass pour ce lieu voient votre profil. Les autres voient seulement une silhouette neutre, votre département et une tranche d’âge (ex. 26-30).')}</div><div class="notice">${T('Nobody owes anyone a reply. Respect refusals. Harassment and impersonation are not allowed.','Personne n’est obligé de répondre. Respectez les refus. Le harcèlement et l’usurpation d’identité sont interdits.')}</div><label class="agreement"><input name="rules" type="checkbox" required>${T('I agree to these community rules.','J’accepte ces règles de communauté.')}</label><button class="button">${T('Save my profile','Enregistrer mon profil')}</button></form><button data-action="signout" class="link">${T('Sign out','Se déconnecter')}</button>`;}
function homeView(){return `<p class="eyebrow">${T('YOUR PLACE, YOUR PACE','VOTRE LIEU, VOTRE RYTHME')}</p><h2 id="card-title">${live()?esc(session.venue_name):T('Where shall we meet?','On se retrouve où ?')}</h2>${live()?`<div class="venue-hero"><span class="badge">${T('You’re here','Vous êtes ici')}</span><p class="session-clock" id="remaining"></p><p>${T('left to make a connection','pour faire connaissance')}</p></div>${roomBlock()}<button data-action="people" class="button wide">${T('See who’s here','Voir qui est là')} →</button><button data-action="talents" class="button secondary wide">${T('Discover talents here','Découvrir les talents ici')}</button><details><summary>${T('My session','Ma session')}</summary>${passBlock()}<p class="quiet">${T('Leaving ends your session.','Quitter termine votre session.')}</p><button data-action="leave" class="button secondary">${T('Leave this place','Quitter ce lieu')}</button></details>`:`<div class="scan-art" aria-hidden="true">${uiIcon('scan')}<span>${T('One place. Real connections.','Un lieu. De vraies rencontres.')}</span></div><p class="lead">${T('Scan the QR displayed in your venue to see who’s here.','Scannez le QR affiché dans votre lieu pour découvrir qui est là.')}</p>`}${venue?`<div class="card"><h3>${esc(venue.name)}</h3><p>${esc(venue.address||'')}</p><p class="quiet">${esc(venue.duration_minutes)} ${T('minutes · joining replaces your current session','minutes · rejoindre remplace votre session actuelle')}</p><button class="button wide" data-action="join">${T('Join this place','Rejoindre ce lieu')}</button></div>`:!live()?`<button class="button wide" data-action="scan">${uiIcon('scan')} ${T('Scan the venue QR','Scanner le QR du lieu')}</button><p class="quiet center">${T('Only people in the same venue are visible. The camera reads QR codes only.','Seules les personnes du même lieu sont visibles. La caméra lit uniquement les QR codes.')}</p>`:''}${passkeyOfferCard()}<p class="pilot-note">${T('Pilot · simulated payments only','Pilote · paiements simulés uniquement')}</p>`;}

function settingsContent(){return `<button class="link" data-view="home">← ${T('Back','Retour')}</button><h2 id="card-title">${T('My profile & settings','Mon profil et réglages')}</h2><form data-form="settings">${field(T('Display name','Nom affiché'),'displayName','text',profile.display_name,'required minlength="2" maxlength="40" autocomplete="nickname"')}${photoField(false)}${genderField(profile.gender||'')}${interestField(profile.interested_in||'',!!profile.interest_consent_at)}${departmentField(profile.department)}${heightField(profile.height_cm)}<label for="bio">${T('About you','Quelques mots sur vous')}</label><textarea id="bio" name="bio" required minlength="1" maxlength="300" rows="3">${esc(profile.bio||'')}</textarea><label for="locale">${T('Language','Langue')}</label><select name="locale" id="locale"><option value="fr" ${profile.locale==='fr'?'selected':''}>Français</option><option value="en" ${profile.locale==='en'?'selected':''}>English</option></select><p class="quiet">${T('Date of birth','Date de naissance')} : ${esc(profile.birth_date)} · ${age(profile.birth_date)} ${T('years old','ans')} · ${T('private, cannot be changed','privée, non modifiable')}</p><p class="quiet">${T('Account','Compte')} : ${esc(user.email||('+'+String(user.phone||'').replace(/^\+/,'')))}</p><button class="button">${T('Save','Enregistrer')}</button></form><h3>${T('My data','Mes données')}</h3><p class="quiet">${T('Get a copy of everything stored about you (JSON file).','Obtenez une copie de tout ce qui est enregistré à votre sujet (fichier JSON).')}</p><button data-action="export" class="button secondary">${T('Download my data','Télécharger mes données')}</button>${pushBlock()}${passkeysBlock()}${signInMethodsBlock()}<h3>${T('Account type','Type de compte')}</h3><p class="quiet">${isPro()?T('Professional (person + professional sheet).','Professionnel (personne + fiche professionnelle).'):T('Person.','Personne.')} ${isPro()?`<button class="link" data-view="pro">${T('My sheet','Ma fiche')}</button>`:`<button class="link" data-action="become-pro">${T('Add a professional sheet','Ajouter une fiche professionnelle')}</button>`}</p>${passes.length?`<h3>${T('My passes','Mes pass')} ${SIM()}</h3>${passes.map(p=>`<p class="quiet">${p.kind==='venue_pass'?esc(p.venue||''):T('Talent subscription','Abonnement talent')} · ${p.status==='refunded'?T('refunded','remboursé'):p.active?T('active until','actif jusqu’au')+' '+esc(when(p.expires_at)):T('expired','expiré')} · ${p.simulated?T('simulated','simulé'):''}</p>`).join('')}`:''}<button data-action="feedback" class="button secondary">${T('Give feedback on the test','Donner mon avis sur le test')}</button><p class="quiet"><a href="./confidentialite.html">${T('Privacy policy','Politique de confidentialité')}</a> · <a href="./cgu.html">${T('Terms of use','Conditions d’utilisation')}</a></p><h3>${T('Delete my account','Supprimer mon compte')}</h3><p class="quiet">${T('Deletes your account, profile and venue history immediately. This cannot be undone.','Supprime immédiatement votre compte, votre profil et votre historique de lieux. Cette action est définitive.')}</p><button data-action="delete" class="button secondary">${T('Delete my account','Supprimer mon compte')}</button>`;}
function settingsView(){const html=settingsContent();const form=html.match(/<form data-form="settings">[\s\S]*?<\/form>/)?.[0]||'';const group=(title,body)=>`<details class="setting-group"><summary>${title}</summary><div>${body}</div></details>`;const tail=html.slice(html.indexOf('<h3>'));const data=tail.slice(0,tail.indexOf('<h3>',4));const account=tail.slice(tail.indexOf(`<h3>${T('Account type','Type de compte')}`));return `<div class="me settings-heading">${avatarUrl?`<img class="avatar" src="${esc(avatarUrl)}" alt="">`:''}<div><p class="eyebrow">${T('YOUR SPACE','VOTRE ESPACE')}</p><h2 id="card-title">${esc(profile.display_name)}</h2></div></div>${group(T('My profile & language','Mon profil et ma langue'),form)}${group(T('Sign-in & security','Connexion et sécurité'),passkeysBlock()+signInMethodsBlock())}${group(T('Notifications','Notifications'),pushBlock())}<button class="settings-link" data-view="help">${T('Help & safety','Aide et sécurité')} →</button>${group(T('My data','Mes données'),data)}${group(T('Account, passes & preferences','Compte, pass et préférences'),account)}${isPro()?`<button class="settings-link" data-view="pro">${T('My professional sheet','Ma fiche professionnelle')} →</button>`:''}${isAdmin?`<a class="settings-link" href="./admin.html">Administration →</a>`:''}<button data-action="signout" class="button secondary wide">${T('Sign out','Se déconnecter')}</button>`;}

function helpView(){return `<button class="link" data-view="home">← ${T('Back','Retour')}</button><h2 id="card-title">${T('Help & safety','Aide et sécurité')}</h2><h3>${T('How it works','Comment ça marche')}</h3><ol><li>${T('Scan the QR code of the place you are in. You see its name and the session length before joining.','Scannez le QR code du lieu où vous êtes. Son nom et la durée de la session s’affichent avant de rejoindre.')}</li><li>${T('During the session (3 hours at most during the test), only people and talents checked in the same place can be discovered.','Pendant la session (3 heures maximum pendant le test), seules les personnes et les talents présents dans le même lieu peuvent être découverts.')}</li><li>${T('Leaving or the end of the session removes you from the place. Your account stays.','Quitter le lieu ou la fin de la session vous retire du lieu. Votre compte est conservé.')}</li></ol><h3>${T('Community rules','Règles de communauté')}</h3><ul><li>${T('Nobody owes anyone a reply. A refusal or a silence is a complete answer.','Personne ne doit de réponse à personne. Un refus ou un silence est une réponse complète.')}</li><li>${T('Payment never buys consent, and never overrides a refusal, a closed conversation or a block.','Un paiement n’achète jamais le consentement et ne contourne jamais un refus, une clôture ou un blocage.')}</li><li>${T('Harassment, impersonation and prohibited content lead to restriction of the account.','Le harcèlement, l’usurpation d’identité et les contenus interdits entraînent la restriction du compte.')}</li><li>${T('One introduction per person per visit. A conversation opens only if the other person accepts and replies. Ending, blocking and reporting are available to everyone, free of charge, at any time.','Une seule présentation par personne et par visite. Une conversation ne s’ouvre que si l’autre personne accepte et répond. Terminer, bloquer et signaler sont disponibles pour tous, gratuitement, à tout moment.')}</li></ul><h3>${T('If something goes wrong','En cas de problème')}</h3><p>${T('UPZONE does not replace the staff of the place or the emergency services. For an immediate problem, speak to the staff; in an emergency in France, call 112 (or 17 for the police).','UPZONE ne remplace ni le personnel du lieu ni les secours. Pour un problème immédiat, adressez-vous au personnel ; en cas d’urgence en France, appelez le 112 (ou le 17 pour la police).')}</p><h3>${T('Your data','Vos données')}</h3><p>${T('Your email and date of birth stay private. Other members only see your display name. You can delete your account at any time from your settings.','Votre e-mail et votre date de naissance restent privés. Les autres membres ne voient que votre nom affiché. Vous pouvez supprimer votre compte à tout moment depuis vos réglages.')}</p><p class="quiet"><a href="./confidentialite.html">${T('Privacy policy','Politique de confidentialité')}</a> · <a href="./cgu.html">${T('Terms of use','Conditions d’utilisation')}</a></p><h3>${T('Three kinds of accounts','Trois types de comptes')}</h3><p>${T('People meet people. Professionals are people with a sheet (“Talents here”) that others in the same place can see and contact. Venues manage their QR code and announcements and never take part in encounters.','Les personnes rencontrent des personnes. Les professionnel·le·s sont des personnes avec une fiche (« Talents ici ») que les autres présents peuvent voir et contacter. Les établissements gèrent leur QR code et leurs annonces et ne participent jamais aux rencontres.')}</p><p class="quiet">${T('Test version: passes and subscriptions are simulated, nothing is charged.','Version de test : les pass et abonnements sont simulés, rien n’est débité.')}</p>`;}
// Profile photo inside a location pin with a small dot at its tip (client request of 10 November 2026).
const SILHOUETTE='<svg class="pin-silhouette" viewBox="0 0 64 64" aria-hidden="true"><circle cx="32" cy="24" r="12"/><path d="M10 58c2-13 11-20 22-20s20 7 22 20z"/></svg>';
function pinPhoto(m,size){return `<span class="pin ${size||''}${m.veiled?' pin-veiled':''}" aria-hidden="true"><span class="pin-head">${m.veiled?SILHOUETTE:m.photo?`<img src="${esc(m.photo)}" alt="" loading="lazy">`:`<span class="pin-initial">${esc(String(m.display_name||'?').trim().charAt(0).toUpperCase())}</span>`}</span><span class="pin-dot"></span></span>`;}
function veiledCard(m){return `<div class="person veiled">${pinPhoto(m)}<span><b>${esc(m.department||'—')}${m.department?` <em class="dept-abbr">${T('dept.','dép.')}</em>`:''}</b><small>${esc(m.age_band||'')} ${T('years','ans')}</small></span></div>`;}
function personCard(m){if(m.veiled)return veiledCard(m);return `<button class="person" data-person="${esc(m.user_id)}">${pinPhoto(m)}<span><b>${esc(m.display_name)}, ${esc(m.age)}${m.height_cm?` · ${esc((m.height_cm/100).toFixed(2).replace('.',lang==='fr'?',':'.'))} m`:''}</b><small>${m.department?`${T('Dept.','Dép.')} ${esc(m.department)} · `:''}${esc(m.bio||'')}</small></span></button>`;}
function veiledNotice(){const n=people.length;return `<div class="notice veiled-notice"><p><b>${n} ${n>1?T('people are here','personnes sont ici'):T('person is here','personne est ici')}.</b> ${T('Take your pass to see who they are.','Prenez votre pass pour voir qui elles sont.')}</p><button class="button" data-action="buy-pass">${T('Get my pass (simulation)','Obtenir mon pass (simulation)')}</button></div>`;}
function peopleView(){return `<button class="link" data-view="home">← ${T('Back','Retour')}</button><h2 id="card-title">${T('Here right now','Ici en ce moment')}</h2><p class="quiet">${esc(session?.venue_name||'')} · ${T('only members present in this place, while their session is live','seulement les membres présents dans ce lieu, pendant leur session')}</p>${!peopleLoaded?`<p role="status">${T('Loading…','Chargement…')}</p>`:people.length?`${people.some(m=>m.veiled)?veiledNotice():''}<div class="people">${people.map(personCard).join('')}</div>`:`<div class="notice">${T('Nobody else for now. Come back in a moment.','Personne d’autre pour l’instant. Revenez dans un moment.')}</div>`}<button class="button secondary" data-action="people">${T('Refresh','Actualiser')}</button>`;}
function personView(){const m=person;return `<button class="link" data-action="people">← ${T('Back','Retour')}</button>${pinPhoto(m,'pin-large')}<h2 id="card-title">${esc(m.display_name)}, ${esc(m.age)}${m.height_cm?` · ${esc((m.height_cm/100).toFixed(2).replace('.',lang==='fr'?',':'.'))} m`:''}</h2><p>${esc(m.bio||'')}</p>${m.department?`<p class="quiet">${T('Département','Département')} ${esc(m.department)}</p>`:''}<p class="quiet">${T('Present in','Présent·e à')} ${esc(session?.venue_name||'')}</p><button class="button" data-view="intro">${T('Send an introduction','Envoyer une présentation')}</button><div class="row"><button class="link" data-action="block" data-user="${esc(m.user_id)}">${T('Block','Bloquer')}</button><button class="link" data-action="report" data-user="${esc(m.user_id)}">${T('Report','Signaler')}</button></div>`;}
function introView(){const m=person;return `<button class="link" data-view="person">← ${T('Back','Retour')}</button><h2 id="card-title">${T('Introduce yourself to','Se présenter à')} ${esc(m.display_name)}</h2><div class="notice">${T('This person is not obliged to respond. Please respect their choice. You can send one message; the conversation opens only if they accept and reply.','Cette personne n’est pas obligée de répondre. Merci de respecter son choix. Vous pouvez envoyer un seul message ; la conversation ne s’ouvre que si elle accepte et répond.')}</div><form data-form="intro"><label for="intro">${T('Your message','Votre message')}</label><textarea id="intro" name="message" required minlength="1" maxlength="500" rows="4"></textarea><small>${T('Up to 500 characters.','500 caractères maximum.')}</small><div class="notice">${T('Stay respectful. Insults, vulgar language or harassment lead to a warning, then suspension, and the person can block you.','Restez respectueux·se. Insultes, propos vulgaires ou harcèlement entraînent un avertissement, puis une suspension, et la personne peut vous bloquer.')}</div><button class="button">${T('Send my introduction','Envoyer ma présentation')}</button></form>`;}
function card(m){return `<img class="avatar" src="${esc(m.photo||'')}" alt=""><span><b>${esc(m.display_name)}, ${esc(m.age)}${m.height_cm?` · ${esc((m.height_cm/100).toFixed(2).replace('.',lang==='fr'?',':'.'))} m`:''}</b>`;}
// Reasons for ending a conversation (decision of 10 November 2026): kept on the server as proof, shown in neutral words.
let endingConv=false;
const END_REASONS=()=>[['not_available',T('I’m no longer available','Je ne suis plus disponible')],['left_venue',T('I left the venue','J’ai quitté le lieu')],['not_interested',T('I’m not interested anymore','Je ne suis plus intéressé·e')],['other',T('Other reason','Autre raison')]];
function endReasonText(r){return ({not_available:T('Reason: no longer available.','Raison : n’est plus disponible.'),left_venue:T('Reason: left the venue.','Raison : a quitté le lieu.'),not_interested:T('Reason: no longer interested.','Raison : n’est plus intéressé·e.'),other:T('Reason: other.','Raison : autre.')})[r]||'';}
function endConvBlock(id){return `<div class="card"><h3>${T('End the conversation','Terminer la conversation')}</h3><p class="quiet">${T('The other person will see a short neutral notice with the reason. You can still block or report.','L’autre personne verra un court avis neutre avec la raison. Vous pouvez aussi bloquer ou signaler.')}</p>${END_REASONS().map(([k,l])=>`<label class="agreement"><input type="radio" name="endReason" value="${k}">${l}</label>`).join('')}<div class="row"><button class="button" data-action="close-confirm" data-conversation="${esc(id)}">${T('End it','Terminer')}</button><button class="button secondary" data-action="close-cancel">${T('Cancel','Annuler')}</button></div></div>`;}
function notifText(n){const p=n.payload||{};switch(n.kind){case 'introduction_received':return T(`${p.from} introduced themselves to you${p.venue?' at '+p.venue:''}.`,`${p.from} s’est présenté·e à vous${p.venue?' à '+p.venue:''}.`);case 'reply_received':return T(`${p.from} accepted and replied. Open the conversation.`,`${p.from} a accepté et répondu. Ouvrez la conversation.`);case 'message_received':return T(`New message from ${p.from}.`,`Nouveau message de ${p.from}.`);case 'conversation_closed':return T('A conversation has ended.','Une conversation est terminée.')+(p.reason?' '+endReasonText(p.reason):'');case 'account_warned':return T('Warning from the UPZONE team: please stay respectful. Another report may lead to suspension.','Avertissement de l’équipe UPZONE : merci de rester respectueux·se. Un nouveau signalement peut entraîner une suspension.');case 'report_handled':return T('Your report has been reviewed. Thank you.','Votre signalement a été examiné. Merci.');case 'account_restricted':return T('Your account has been restricted after a review.','Votre compte a été restreint après examen.');case 'account_reinstated':return T('Your account has been reinstated.','Votre compte a été rétabli.');default:return n.kind;}}
function notifFeed(){if(!notifs||!notifs.items.length)return '';const items=notifs.items.slice(0,8);return `<h3>${T('Activity','Activité')}</h3><div class="feed">${items.map(n=>`<p class="${n.read?'read':''}">${n.payload?.conversation?`<button class="link" data-conversation="${esc(n.payload.conversation)}">${esc(notifText(n))}</button>`:esc(notifText(n))}<small>${esc(new Date(n.created_at).toLocaleString(lang==='fr'?'fr-FR':'en-GB',{dateStyle:'short',timeStyle:'short'}))}</small></p>`).join('')}</div>`;}
function messagesView(){if(!inbox)return `<button class="link" data-view="home">← ${T('Back','Retour')}</button><h2 id="card-title">${T('Messages','Messages')}</h2><p role="status">${T('Loading…','Chargement…')}</p>`;const r=inbox.received,c=inbox.conversations,s=inbox.sent;return `<button class="link" data-view="home">← ${T('Back','Retour')}</button><h2 id="card-title">${T('Messages','Messages')}</h2>${notifs?.items?.length?`<details><summary>${T('Recent activity','Activité récente')}</summary>${notifFeed()}</details>`:''}${r.length?`<h3>${T('Introductions received','Présentations reçues')}</h3><div class="people">${r.map(i=>`<div class="person static"><div class="who">${card(i.from)}<small>${esc(i.venue||'')}</small></span></div><p class="bubble">${esc(i.message)}</p><div class="row"><button class="button" data-action="accept" data-intro="${esc(i.id)}">${T('Reply & accept','Répondre et accepter')}</button><button class="button secondary" data-action="decline" data-intro="${esc(i.id)}">${T('Decline','Décliner')}</button></div><div class="row"><button class="link" data-action="block" data-user="${esc(i.from.user_id)}">${T('Block','Bloquer')}</button><button class="link" data-action="report" data-user="${esc(i.from.user_id)}">${T('Report','Signaler')}</button></div></div>`).join('')}</div>`:''}<h3>${T('Conversations','Conversations')}</h3>${c.length?`<div class="people">${c.map(x=>`<button class="person" data-conversation="${esc(x.id)}">${card(x.with)}<small>${x.closed_at?T('Conversation ended','Conversation terminée'):x.last?.locked?'🔒 '+T('Reply hidden until you have a pass','Réponse masquée tant que vous n’avez pas de pass'):esc(x.last?.body||'')}</small></span>${x.unread>0?`<i class="badge-dot">${x.unread}</i>`:''}</button>`).join('')}</div>`:`<p class="quiet">${T('No conversation yet. A conversation opens when someone accepts your introduction and replies, or when you accept one.','Pas encore de conversation. Une conversation s’ouvre quand quelqu’un accepte votre présentation et répond, ou quand vous en acceptez une.')}</p>`}${s.length?`<h3>${T('Introductions sent','Présentations envoyées')}</h3><div class="people">${s.map(i=>`<div class="person static"><div class="who">${card(i.to)}<small>${T('Waiting — no reply is a complete answer.','En attente — l’absence de réponse est une réponse.')}</small></span></div></div>`).join('')}</div>`:''}<button class="button secondary" data-action="messages">${T('Refresh','Actualiser')}</button>`;}
function acceptView(){const i=inbox?.received.find(x=>x.id===view.id);if(!i)return messagesView();return `<button class="link" data-action="messages">← ${T('Back','Retour')}</button><h2 id="card-title">${T('Reply to','Répondre à')} ${esc(i.from.display_name)}</h2><p class="bubble">${esc(i.message)}</p><p class="quiet">${T('Accepting opens a conversation. You can end or block at any time.','Accepter ouvre une conversation. Vous pouvez la terminer ou bloquer à tout moment.')}</p><form data-form="accept" data-intro="${esc(i.id)}"><label for="reply">${T('Your reply','Votre réponse')}</label><textarea id="reply" name="reply" required minlength="1" maxlength="2000" rows="3"></textarea><button class="button">${T('Send and open the conversation','Envoyer et ouvrir la conversation')}</button></form>`;}
function conversationView(){if(!thread)return `<button class="link" data-action="messages">← ${T('Back','Retour')}</button><p role="status">${T('Loading…','Chargement…')}</p>`;const t=thread;return `<button class="link" data-action="messages">← ${T('Back','Retour')}</button><div class="me">${card(t.with)}<small>${esc(t.venue||'')}</small></span></div><div class="thread">${t.messages.map(m=>`<p class="bubble ${m.mine?'mine':''} ${m.locked?'locked':''}">${m.locked?'🔒 '+T('Reply hidden until you have a pass','Réponse masquée tant que vous n’avez pas de pass'):esc(m.body)}${!m.mine&&!m.locked?(translations[m.id]?`<span class="translated">${translations[m.id].same?T('(already in your language)','(déjà dans votre langue)'):esc(translations[m.id].text)+' <small>· '+T('translation','traduction')+'</small>'}</span>`:translating[m.id]?`<span class="translated">…</span>`:`<button class="link tiny" data-action="translate" data-msg="${esc(m.id)}">${T('Translate','Traduire')}</button>`):''}</p>`).join('')}${t.closed_at?`<p class="quiet center">${t.closed_by_me?T('You ended this conversation.','Vous avez terminé cette conversation.'):T('This conversation has ended.','Cette conversation est terminée.')}${t.closed_reason?` ${esc(endReasonText(t.closed_reason))}`:''}</p>`:''}</div>${meetingBlock(t)}${t.locked?`<div class="notice">${T('This person accepted and replied. A pass for this place unlocks the conversation.','Cette personne a accepté et répondu. Un pass pour ce lieu débloque la conversation.')} ${SIM()} ${t.live!==false&&live()&&session.venue_name===t.venue?`<button class="button" data-action="buy-pass" data-conversation="${esc(t.id)}">${T('Get my pass (simulation)','Obtenir mon pass (simulation)')}</button>`:`<p class="quiet">${T('Passes are obtained while checked in at the place.','Le pass s’obtient pendant une session dans le lieu.')}</p>`}</div>`:''}${!t.closed_at&&t.live===false?`<div class="notice">${T('You are no longer in the same place. The conversation stays readable here and continues when you are both checked in there again. A new visit, a new choice for each of you.','Vous n’êtes plus dans le même lieu. La conversation reste lisible ici et reprend quand vous y êtes de nouveau tous les deux. Nouvelle visite, nouveau choix pour chacun.')}</div>`:''}${t.closed_at||t.locked||t.live===false?'':`<label class="agreement small"><input type="checkbox" data-toggle="autotranslate" ${autoTranslate?'checked':''}>${T('Translate received messages automatically','Traduire automatiquement les messages reçus')} <small>(${T('sent to DeepL only when you ask','envoyés à DeepL seulement à votre demande')})</small></label><form data-form="message" data-conversation="${esc(t.id)}"><label for="body" class="sr">${T('Message','Message')}</label><textarea id="body" name="body" required minlength="1" maxlength="2000" rows="2" placeholder="${T('Write a message','Écrire un message')}"></textarea><button type="button" class="link tiny" data-action="translate-draft">${lang==='fr'?'Traduire mon message en anglais':'Translate my message into French'}</button><button class="button">${T('Send','Envoyer')}</button></form>`}${endingConv&&!t.closed_at?endConvBlock(t.id):''}<div class="row">${t.closed_at?'':`<button class="link" data-action="close" data-conversation="${esc(t.id)}">${T('End the conversation','Terminer la conversation')}</button>`}<button class="link" data-action="block" data-user="${esc(t.with.user_id)}">${T('Block','Bloquer')}</button><button class="link" data-action="report" data-user="${esc(t.with.user_id)}" data-conversation="${esc(t.id)}">${T('Report','Signaler')}</button></div>`;}
function meetingBlock(t){const m=t.meeting||{};if(t.closed_at||!m.can_ask)return '';if(m.agreed)return `<div class="notice meet">${T('You both said yes: meet at a public spot of the venue, for example the counter.','Vous avez dit oui tous les deux : retrouvez-vous à un point public du lieu, par exemple le comptoir.')}</div>`;if(m.other_answered&&m.my_answer==null&&!meetingDismissed[t.id])return `<div class="notice meet" id="meeting-prompt">${T('Shall we meet? Only if you both say yes.','On se rencontre ? Seulement si vous dites oui tous les deux.')}<div class="row"><button class="button" data-action="meet" data-answer="yes" data-conversation="${esc(t.id)}">${T('Yes','Oui')}</button><button class="button secondary" data-action="meet" data-answer="no" data-conversation="${esc(t.id)}">${T('No','Non')}</button></div><small id="meeting-count">5</small></div>`;if(m.my_answer===true)return `<p class="quiet center">${T('You proposed to meet. The conversation continues either way.','Vous avez proposé de vous rencontrer. La conversation continue quoi qu’il arrive.')}</p>`;return `<p class="center"><button class="link" data-action="meet" data-answer="yes" data-conversation="${esc(t.id)}">${T('Propose to meet','Proposer de se rencontrer')}</button></p>`;}
function armMeetingPrompt(){if(meetingTimer){clearInterval(meetingTimer);meetingTimer=null;}const node=document.getElementById('meeting-prompt');if(!node||!thread)return;let left=5;const id=thread.id;meetingTimer=setInterval(()=>{left--;const c=document.getElementById('meeting-count');if(c)c.textContent=String(left);if(left<=0){clearInterval(meetingTimer);meetingTimer=null;meetingDismissed[id]=true;if(view==='conversation'&&thread?.id===id)render();}},1000);}
function reportView(){const r=reportTarget;return `<button class="link" data-action="messages">← ${T('Back','Retour')}</button><h2 id="card-title">${T('Report a problem','Signaler un problème')}</h2><p class="quiet">${T('Your report is reviewed by the moderation team. The person reported is never told who reported them.','Votre signalement est examiné par la modération. La personne signalée ne sait jamais qui l’a signalée.')}</p><form data-form="report" data-user="${esc(r.user)}" data-conversation="${esc(r.conversation||'')}"><label for="category">${T('Reason','Motif')}</label><select id="category" name="category" required><option value="harassment">${T('Harassment','Harcèlement')}</option><option value="insults">${T('Insults or vulgar language','Insultes ou propos vulgaires')}</option><option value="inappropriate">${T('Inappropriate messages','Propos inappropriés')}</option><option value="impersonation">${T('Impersonation','Usurpation d’identité')}</option><option value="prohibited">${T('Prohibited content','Contenu interdit')}</option><option value="other">${T('Other','Autre')}</option></select><label for="details">${T('Details (optional)','Précisions (facultatif)')}</label><textarea id="details" name="details" maxlength="1000" rows="3"></textarea><label class="agreement"><input name="alsoBlock" type="checkbox" checked>${T('Also block this person','Bloquer aussi cette personne')}</label><button class="button">${T('Send the report','Envoyer le signalement')}</button></form><p class="quiet">${T('In an emergency, speak to the staff or call 112.','En cas d’urgence, adressez-vous au personnel ou appelez le 112.')}</p>`;}
async function withPhotos(list,key){return Promise.all(list.map(async x=>{const m=key?x[key]:x;if(m?.avatar_path&&!m.photo){const {data}=await client.storage.from('avatars').createSignedUrl(m.avatar_path,900);m.photo=data?.signedUrl||'';}return x;}));}
async function loadInbox(){view='messages';render();const data=await rpc('my_inbox');try{notifs=await rpc('my_notifications',{p_mark_read:true});}catch{}await withPhotos(data.received,'from');await withPhotos(data.sent,'to');await withPhotos(data.conversations,'with');inbox=data;render();}
function stopThread(){if(threadTimer){clearInterval(threadTimer);threadTimer=null;}}
async function openThread(id,quiet){if(!thread||thread.id!==id)endingConv=false;if(!quiet){thread=null;view='conversation';render();}const t=await rpc('conversation_messages',{p_id:id});await withPhotos([t],'with');const box=document.querySelector('.thread');const atBottom=!box||box.scrollHeight-box.scrollTop-box.clientHeight<40;thread=t;if(view==='conversation'){render();armMeetingPrompt();autoTranslateThread().catch(()=>{});const b=document.querySelector('.thread');if(b&&(atBottom||!quiet))b.scrollTop=b.scrollHeight;}if(!quiet){stopThread();threadTimer=setInterval(()=>{if(view==='conversation'&&thread?.id===id&&!busy){if(!typing())openThread(id,true).catch(()=>{});}else stopThread();},8000);}}
async function loadPeople(){peopleLoaded=false;people=[];person=null;view='people';render();const rows=await rpc('venue_members');const signed=await Promise.all(rows.map(async m=>{if(!m.avatar_path)return {...m,photo:''};const {data}=await client.storage.from('avatars').createSignedUrl(m.avatar_path,900).catch(()=>({data:null}));return {...m,photo:data?.signedUrl||''};}));people=signed;peopleLoaded=true;render();}
function scanView(){return `<button class="link" data-view="home">← ${T('Back','Retour')}</button><h2 id="card-title">${T('Scan the QR code','Scanner le QR code')}</h2><p class="quiet">${T('Point the camera at the QR code displayed in the venue.','Pointez la caméra vers le QR code affiché dans l’établissement.')}</p><video id="scan-video" class="scanner" playsinline muted autoplay></video><canvas id="scan-canvas" hidden></canvas><p id="scan-status" class="quiet" role="status">${T('Starting the camera…','Démarrage de la caméra…')}</p><p class="quiet">${T('The camera is used only to read the QR code. No photo is taken or stored.','La caméra sert uniquement à lire le QR code. Aucune photo n’est prise ni conservée.')}</p>`;}
function stopScan(){if(scanTimer){clearTimeout(scanTimer);scanTimer=null;}if(scanStream){scanStream.getTracks().forEach(t=>t.stop());scanStream=null;}}
function tokenFrom(text){const value=String(text||'').trim();try{const param=new URL(value).searchParams.get('venue');if(param)return param;}catch{}return /^[A-Za-z0-9_-]{32,256}$/.test(value)?value:'';}
async function startScan(){view='scan';render();const video=document.getElementById('scan-video'),canvas=document.getElementById('scan-canvas'),status=document.getElementById('scan-status');if(!navigator.mediaDevices?.getUserMedia){view='home';render();notice(T('This browser cannot use the camera here. Open the QR code with your phone camera app, or enter the code below.','Ce navigateur ne peut pas utiliser la caméra ici. Ouvrez le QR code avec l’appareil photo du téléphone, ou saisissez le code ci-dessous.'),true);return;}
try{scanStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});}catch(e){view='home';render();notice(e?.name==='NotAllowedError'?T('Camera access was refused. Open the QR code with your phone camera app, or enter the code below.','Accès à la caméra refusé. Ouvrez le QR code avec l’appareil photo du téléphone, ou saisissez le code ci-dessous.'):T('The camera could not be started. Open the QR code with your phone camera app, or enter the code below.','La caméra n’a pas pu démarrer. Ouvrez le QR code avec l’appareil photo du téléphone, ou saisissez le code ci-dessous.'),true);return;}
video.srcObject=scanStream;try{await video.play();}catch{}status.textContent=T('Looking for a QR code…','Recherche du QR code…');const detector=('BarcodeDetector' in window)?new BarcodeDetector({formats:['qr_code']}):null;const ctx=canvas.getContext('2d',{willReadFrequently:true});
const tick=async()=>{if(view!=='scan'||!scanStream)return;let found='';try{if(video.readyState>=2){if(detector){const codes=await detector.detect(video);found=codes[0]?.rawValue||'';}else{canvas.width=video.videoWidth;canvas.height=video.videoHeight;ctx.drawImage(video,0,0);const image=ctx.getImageData(0,0,canvas.width,canvas.height);found=jsQR(image.data,image.width,image.height,{inversionAttempts:'dontInvert'})?.data||'';}}}catch{}
const token=tokenFrom(found);if(token){stopScan();invite=token;sessionStorage.setItem('prorod-invite',invite);view='home';await run(async()=>{venue=await rpc('preview_venue',{p_token:invite});render();});render();return;}if(found){status.textContent=T('This QR code is not a venue invitation.','Ce QR code n’est pas une invitation de lieu.');}scanTimer=setTimeout(tick,250);};tick();}
async function translateText(text,target){const {data,error}=await client.functions.invoke('translate',{body:{text,target}});if(error){let code='translation_failed';try{const body=await error.context?.json();if(body?.error)code=body.error;}catch{}throw new Error(code);}if(data?.error)throw new Error(data.error);return data;}
async function translateMessage(id){if(!thread||translations[id]||translating[id])return;const m=thread.messages.find(x=>x.id===id);if(!m||m.mine||m.locked||!m.body)return;translating[id]=true;render();try{const r=await translateText(m.body,lang);translations[id]={text:r.text,same:String(r.source||'').toLowerCase().startsWith(lang)};}catch(e){delete translating[id];if(view==='conversation')render();notice(friendly(e),true);return;}delete translating[id];if(view==='conversation'&&thread?.id)render();}
async function autoTranslateThread(){if(!autoTranslate||!thread)return;for(const m of thread.messages.slice(-20)){if(!m.mine&&!m.locked&&m.body&&!translations[m.id]&&!translating[m.id])await translateMessage(m.id);}}
async function loadTalents(){talentsLoaded=false;talents=[];talent=null;view='talents';render();const rows=await rpc('venue_talents')||[];talents=await withPhotos(rows);talentsLoaded=true;render();}
// Feedback after one hour of real use (foreground time, per device), at most two reminders.
const USE_KEY='prorod-use-ms';
function usedMs(){return Number(localStorage.getItem(USE_KEY))||0;}
function tickUse(){if(!user||document.visibilityState!=='visible')return;localStorage.setItem(USE_KEY,String(usedMs()+30000));maybeFeedback();}
function maybeFeedback(){if(localStorage.getItem('prorod-feedback-done')||!user||!complete(profile))return;if(usedMs()<60*60*1000)return;const reminders=Number(localStorage.getItem('prorod-feedback-reminders'))||0;const until=Number(localStorage.getItem('prorod-feedback-snooze'))||0;if(reminders>=3||Date.now()<until)return;openFeedback(false);}
function openFeedback(manual){let d=document.getElementById('feedback-dialog');if(!d){document.body.insertAdjacentHTML('beforeend',feedbackDialog());d=document.getElementById('feedback-dialog');}if(d&&!d.open){if(!manual)localStorage.setItem('prorod-feedback-reminders',String((Number(localStorage.getItem('prorod-feedback-reminders'))||0)+1));d.showModal();}}
function snoozeFeedback(){localStorage.setItem('prorod-feedback-snooze',String(Date.now()+30*60*1000));document.getElementById('feedback-dialog')?.close();}
document.addEventListener('visibilitychange',refreshCounts);setInterval(refreshCounts,60000);setInterval(tickUse,30000);
// Unread items (introductions waiting, unread messages, notifications): the in-app dot and the red badge on the
// installed app icon (Badging API: iPhone/iPad 16.4+ home-screen app once notifications are allowed, Chrome/Edge on
// computers; not available on Android). Only a number, never any content.
function unreadTotal(){return (inbox?inbox.received.length+inbox.conversations.reduce((a,c)=>a+(c.unread||0),0):0)+(notifs?.unread||0);}
function syncAppBadge(){if(!('setAppBadge' in navigator))return;const n=user?unreadTotal():0;try{(n>0?navigator.setAppBadge(n):navigator.clearAppBadge()).catch(()=>{});}catch{}}
// ---- Push notifications (Web Push) -------------------------------------------------------------------------------
// The phone shows a generic sentence and the red count on the icon even when the app is closed. iPhone: only in the
// app installed on the Home Screen (iOS 16.4+). The subscription is saved on the server for the signed-in member only
// and removed at sign-out, so a shared phone never receives someone else's notifications.
let pushOn=false,linkPhone=null;
const isIOS=()=>/iPhone|iPad|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);
const standalone=()=>matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;
function pushSupport(){if(!config.vapidPublicKey)return 'unsupported';if(!('serviceWorker' in navigator)||!('PushManager' in window)||!('Notification' in window))return isIOS()&&!standalone()?'needs-install':'unsupported';if(Notification.permission==='denied')return 'denied';return pushOn?'on':'off';}
function keyBytes(b64){const pad='='.repeat((4-b64.length%4)%4);const raw=atob((b64+pad).replace(/-/g,'+').replace(/_/g,'/'));return Uint8Array.from(raw,c=>c.charCodeAt(0));}
async function pushRegistration(){return navigator.serviceWorker.getRegistration('./').then(r=>r||navigator.serviceWorker.register('./sw.js')).then(()=>navigator.serviceWorker.ready);}
async function checkPush(){if(pushSupport()==='unsupported'||pushSupport()==='needs-install'||!user)return;try{const reg=await pushRegistration();const sub=await reg.pushManager.getSubscription();pushOn=!!sub&&Notification.permission==='granted';
  if(pushOn){const j=sub.toJSON();await rpc('save_push_subscription',{p_endpoint:j.endpoint,p_p256dh:j.keys.p256dh,p_auth:j.keys.auth});}}catch{pushOn=false;}}
async function pushEnable(){const perm=await Notification.requestPermission();if(perm!=='granted'){notice(T('Notifications were not allowed. You can allow them later in your phone settings.','Les notifications n’ont pas été autorisées. Vous pourrez les autoriser plus tard dans les réglages du téléphone.'),true);return;}
  const reg=await pushRegistration();const sub=(await reg.pushManager.getSubscription())||await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:keyBytes(config.vapidPublicKey)});const j=sub.toJSON();
  await rpc('save_push_subscription',{p_endpoint:j.endpoint,p_p256dh:j.keys.p256dh,p_auth:j.keys.auth});pushOn=true;syncAppBadge();render();notice(T('Notifications are on for this phone.','Notifications activées sur ce téléphone.'));}
async function pushDisable(quiet=false){try{if('serviceWorker' in navigator){const reg=await navigator.serviceWorker.getRegistration('./');const sub=reg&&await reg.pushManager?.getSubscription();if(sub){if(user)await rpc('delete_push_subscription',{p_endpoint:sub.endpoint}).catch(()=>{});await sub.unsubscribe().catch(()=>{});}}}catch{}
  pushOn=false;if('clearAppBadge' in navigator)navigator.clearAppBadge().catch(()=>{});if(!quiet){render();notice(T('Notifications are off for this phone.','Notifications désactivées sur ce téléphone.'));}}
function pushBlock(){const st=pushSupport();const intro=`<h3>${T('Notifications','Notifications')}</h3><p class="quiet">${T('A short alert and the red number on the app icon when someone introduces themselves, replies or writes to you. Never a name or a message on the lock screen.','Une courte alerte et le nombre en rouge sur l’icône quand quelqu’un se présente, vous répond ou vous écrit. Jamais de nom ni de message sur l’écran verrouillé.')}</p>`;
  if(st==='on')return intro+`<p>✅ ${T('On for this phone.','Activées sur ce téléphone.')}</p><button data-action="push-off" class="button secondary">${T('Turn off on this phone','Désactiver sur ce téléphone')}</button>`;
  if(st==='off')return intro+`<button data-action="push-on" class="button secondary">${T('Turn on notifications','Activer les notifications')}</button>`;
  if(st==='denied')return intro+`<p class="quiet">${T('Notifications are blocked for UPZONE in your phone or browser settings. Allow them there, then come back.','Les notifications sont bloquées pour UPZONE dans les réglages du téléphone ou du navigateur. Autorisez-les, puis revenez ici.')}</p>`;
  if(st==='needs-install')return intro+`<p class="quiet">${T('On iPhone, install UPZONE on your Home Screen first (Safari → Share → Add to Home Screen), then open it from the icon.','Sur iPhone, installez d’abord UPZONE sur l’écran d’accueil (Safari → Partager → Sur l’écran d’accueil), puis ouvrez-le depuis l’icône.')}</p>`;
  return intro+`<p class="quiet">${T('This browser cannot receive notifications.','Ce navigateur ne peut pas recevoir de notifications.')}</p>`;}
// ---- Passkeys (Face ID, fingerprint or phone PIN) -----------------------------------------------------------------
// Preferred way back in; SMS or e-mail stay as the fallback. Switched on by config.providers.passkey only once the app's
// final address is fixed: a passkey is bound to the domain (Relying Party ID) and would stop working after a move.
let passkeys=null;
const passkeyReady=()=>!!(config.providers?.passkey&&window.PublicKeyCredential&&window.isSecureContext);
const passkeyLaterKey=()=>'upzone-passkey-later-'+(user?.id||'');
function passkeyMessage(e){const code=e?.code||e?.error_code||'',cause=e?.cause?.name||e?.name||'';
  if(code==='ERROR_CEREMONY_ABORTED'||cause==='NotAllowedError'||cause==='AbortError')return T('Cancelled. No passkey on this phone? Use your phone number or email below.','Annulé. Pas de clé d’accès sur ce téléphone ? Utilisez votre numéro ou votre e-mail ci-dessous.');
  if(code==='ERROR_AUTHENTICATOR_PREVIOUSLY_REGISTERED'||cause==='InvalidStateError')return T('This phone already has a passkey for your account.','Ce téléphone a déjà une clé d’accès pour votre compte.');
  if(/not_enabled/.test(code)||/not_enabled/.test(e?.message||''))return T('Passkeys are not switched on yet for this app.','Les clés d’accès ne sont pas encore activées pour cette application.');
  if(code==='webauthn_challenge_expired')return T('The request expired. Please try again.','La demande a expiré. Réessayez.');
  return friendly(e);}
async function loadPasskeys(){if(!passkeyReady()||!user){passkeys=null;return;}try{const {data,error}=await client.auth.passkey.list();passkeys=error?null:(data||[]);}catch{passkeys=null;}}
function passkeyOfferCard(){if(!passkeyReady()||!passkeys||passkeys.length)return '';try{if(localStorage.getItem(passkeyLaterKey()))return '';}catch{}
  return `<div class="card"><h3>🔑 ${T('Quick, secure sign-in','Connexion rapide et sécurisée')}</h3><p class="quiet">${T('Next time, sign in with Face ID, your fingerprint or your phone PIN: no code to wait for. Your fingerprint and face never leave your phone.','La prochaine fois, connectez-vous avec Face ID, votre empreinte ou le code de votre téléphone : plus de code à attendre. Votre empreinte et votre visage ne quittent jamais votre téléphone.')}</p><button class="button" data-action="passkey-register">${T('Enable','Activer')}</button><button class="link" data-action="passkey-later">${T('Later','Plus tard')}</button></div>`;}
function passkeysBlock(){if(!passkeyReady())return '';const list=passkeys||[];
  return `<h3>${T('Passkeys','Clés d’accès')}</h3><p class="quiet">${T('Sign in with Face ID, fingerprint or phone PIN. If a passkey is unavailable, your phone number or email still work.','Connexion avec Face ID, empreinte ou code du téléphone. Si la clé n’est pas disponible, votre numéro ou votre e-mail fonctionnent toujours.')}</p>${list.length?`<ul class="plain">${list.map(k=>`<li>🔑 ${esc(k.friendly_name||T('Passkey','Clé d’accès'))} · ${esc(new Date(k.created_at).toLocaleDateString(lang))} <button class="link" data-action="passkey-delete" data-id="${esc(k.id)}">${T('Remove','Retirer')}</button></li>`).join('')}</ul>`:''}<button class="button secondary" data-action="passkey-register">${T('Add a passkey on this phone','Ajouter une clé d’accès sur ce téléphone')}</button>`;}
// ---- Sign-in methods: one account, several ways in ----------------------------------------------------------------
// Adding a phone number (or an e-mail) to the current account means both sign-in buttons open the same profile, instead
// of « Continue with my phone number » creating a second, empty account.
function signInMethodsBlock(){const em=user?.email,ph=user?.phone;return `<h3>${T('Ways to sign in','Moyens de connexion')}</h3><p class="quiet">${T('Add your phone number and your email to this account: both will open the same profile.','Ajoutez votre numéro et votre e-mail à ce compte : les deux ouvriront le même profil.')}</p><p>✉️ ${em?esc(em):`<i>${T('no email yet','pas encore d’e-mail')}</i>`}<br>📱 ${ph?esc('+'+String(ph).replace(/^\+/,'')):`<i>${T('no phone number yet','pas encore de numéro')}</i>`}</p>`
  +(!ph&&config.providers?.phone?(linkPhone?`<form data-form="link-phone-code"><p class="quiet">${T('We sent a code by SMS to','Nous avons envoyé un code par SMS au')} ${esc(linkPhone)}.</p>${field(T('6-digit code','Code à 6 chiffres'),'linkCode','text','','required inputmode="numeric" pattern="[0-9]{6}" autocomplete="one-time-code"')}<button class="button secondary">${T('Confirm my number','Confirmer mon numéro')}</button></form>`:`<form data-form="link-phone">${field(T('Add my mobile number (international format)','Ajouter mon numéro de mobile (format international)'),'linkPhone','tel','+33','required autocomplete="tel" pattern="\\+[0-9]{8,15}"')}<button class="button secondary">${T('Send me a code','M’envoyer un code')}</button></form>`):'')
  +(!em?`<form data-form="link-email">${field(T('Add my email','Ajouter mon e-mail'),'linkEmail','email','','required autocomplete="email" maxlength="254"')}<small>${T('We will send a confirmation link. To sign in with this email later, use « Forgot password? » once to choose a password.','Nous enverrons un lien de confirmation. Pour vous connecter ensuite avec cet e-mail, utilisez une fois « Mot de passe oublié ? » pour choisir un mot de passe.')}</small><button class="button secondary">${T('Add this email','Ajouter cet e-mail')}</button></form>`:'');}
async function refreshCounts(){if(!user||document.hidden)return;try{const [n,i]=await Promise.all([rpc('my_notifications',{p_mark_read:false}),rpc('my_inbox')]);notifs=n;inbox=i;if(view==='home'&&complete(profile)&&!typing())render();else syncAppBadge();}catch{}}
// Typed values survive any redraw (an error, a language switch, the counts refresh): every visible form is read before
// the screen is rebuilt and refilled after. Passwords and files are never copied (the chosen photo is kept in pendingPhoto).
let pendingPhoto=null;
// Redrawing the screen replaces the field being typed in, which closes the phone keyboard: periodic refreshes wait while a field has focus.
function typing(){const a=document.activeElement;return !!a&&root.contains(a)&&/^(INPUT|TEXTAREA|SELECT)$/.test(a.tagName)&&!['checkbox','radio','button','submit','file'].includes(a.type);}
function snapshotForms(){const d={};root.querySelectorAll('form[data-form]').forEach(f=>{const o={};f.querySelectorAll('input,textarea,select').forEach(el=>{if(!el.name||['password','file','hidden','submit'].includes(el.type))return;o[el.name]=el.type==='checkbox'?el.checked:el.value;});d[f.dataset.form]=o;});return d;}
function restoreForms(d){for(const [k,o] of Object.entries(d)){const f=root.querySelector(`form[data-form="${k}"]`);if(!f)continue;for(const [n,v] of Object.entries(o)){const el=f.elements.namedItem(n);if(!el||!('value' in el)||['password','file','hidden'].includes(el.type))continue;if(el.type==='checkbox')el.checked=v;else el.value=v;}}}
function uiIcon(name){const paths={place:'<path d="M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',messages:'<path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5H4l-2 2V11.5a9.5 9.5 0 0 1 19 0Z"/>',profile:'<circle cx="12" cy="7" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3Z"/>',scan:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5M7 7h3v3H7zm7 0h3v3h-3zM7 14h3v3H7zm7 0h3v3h-3z"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]}</svg>`;}
function memberNav(){if(!user||!complete(profile)||isVenue()||recovery)return '';const active=['messages','conversation','report'].includes(view)||typeof view==='object'?'messages':['settings','help','pro','pro-edit'].includes(view)?'profile':'place';return `<nav class="member-nav" aria-label="${T('Main navigation','Navigation principale')}">${[['place','data-view="home"',T('The venue','Le lieu')],['messages','data-action="messages"',T('Messages','Messages')],['profile','data-view="settings"',T('Profile','Profil')]].map(([id,attr,label])=>`<button ${attr} ${active===id?'aria-current="page"':''}>${uiIcon(id)}<span>${label}</span>${id==='messages'&&unreadTotal()>0?`<i class="nav-badge">${unreadTotal()}</i>`:''}</button>`).join('')}</nav>`;}
function render(){const drafts=snapshotForms();const opened=[...root.querySelectorAll('details[open]')].map(d=>d.querySelector('summary')?.textContent);document.body.dataset.screen=user?(typeof view==='string'?view:'accept'):mode;document.documentElement.lang=lang;syncAppBadge();localStorage.setItem('prorod-lang',lang);document.getElementById('headline').innerHTML=T('A first step.<br>A real connection.','Un premier pas.<br>Une vraie rencontre.');document.getElementById('intro-copy').textContent=T('Your own space, at your own pace.','Votre espace, à votre rythme.');document.getElementById('demo-link').textContent=T('Explore the fictional demo','Explorer la démo fictive');root.innerHTML=recovery&&user?`<h2 id="card-title">${T('Choose a new password','Choisissez un nouveau mot de passe')}</h2><form data-form="password">${field(T('New password','Nouveau mot de passe'),'password','password','','required minlength="12" autocomplete="new-password"')}<button class="button">${T('Save password','Enregistrer')}</button></form>`:!user?authView():!accountType?typeView():!complete(profile)?(isVenue()?venueProfileView():profileView()):isVenue()?(view==='venue-settings'?venueSettingsView():view==='help'?helpView():venueHomeView()):(isPro()&&!proData&&!sessionStorage.getItem('prorod-pro-later'))?proSheetView(false):view==='pro'?proView():view==='pro-edit'?proSheetView(true):view==='talents'?talentsView():view==='talent'&&talent?talentView():view==='settings'?settingsView():view==='help'?helpView():view==='scan'?scanView():view==='people'?peopleView():view==='person'&&person?personView():view==='intro'&&person?introView():view==='messages'?messagesView():(view&&view.name==='accept')?acceptView():view==='conversation'?conversationView():view==='report'&&reportTarget?reportView():homeView();root.insertAdjacentHTML('beforeend',memberNav());root.querySelectorAll('details').forEach(d=>{if(opened.includes(d.querySelector('summary')?.textContent))d.open=true;});restoreForms(drafts);if(user&&complete(profile)&&!document.getElementById('feedback-dialog'))document.body.insertAdjacentHTML('beforeend',feedbackDialog());clock();}
function clock(){const node=document.getElementById('remaining');if(!node||!session)return;const seconds=Math.max(0,Math.ceil((Date.parse(session.expires_at)-Date.now())/1000));node.textContent=`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;if(!seconds){session=null;render();}}
async function rpc(name,args){const {data,error}=await client.rpc(name,args);if(error)throw error;return data;}
async function load(){const {data,error}=await client.auth.getUser();if(error){user=null;profile=null;session=null;render();showLinkError();if(error.name!=='AuthSessionMissingError')notice(friendly(error),true);return;}user=data.user;if(!user){render();showLinkError();return;}const p=await client.from('profiles').select('*').eq('user_id',user.id).maybeSingle();if(p.error)throw p.error;profile=p.data;try{accountType=await rpc('my_account_type');}catch{accountType=null;}if(profile?.account_type)accountType=profile.account_type;try{settings=Object.assign(settings,await rpc('app_settings_public')||{});}catch{}const q=await client.from('venue_sessions').select('*').is('ended_at',null).eq('user_id',user.id).maybeSingle();if(q.error)throw q.error;session=q.data;await loadAvatar();try{isAdmin=await rpc('is_admin')===true;}catch{isAdmin=false;}if(complete(profile)&&isVenue()){try{venueData=await rpc('my_venue');}catch(e){venueData=null;notice(friendly(e),true);}}else if(complete(profile)){try{inbox=await rpc('my_inbox');notifs=await rpc('my_notifications',{p_mark_read:false});}catch{inbox=null;notifs=null;}try{passes=await rpc('my_passes')||[];}catch{passes=[];}if(isPro()){try{proData=await rpc('my_pro_profile');}catch{proData=null;}}room=null;if(live()){try{room=await rpc('venue_room');}catch{room=null;}}}if(complete(profile)&&invite){try{venue=await rpc('preview_venue',{p_token:invite});}catch(e){venue=null;notice(friendly(e),true);}}render();showLinkError();if(user){checkPush().then(()=>{if(view==='settings')render();});loadPasskeys().then(()=>{if(passkeys&&(view==='settings'||view==='home'))render();});}}
async function run(fn){if(busy)return;busy=true;notice('');root.querySelectorAll('button,input,select').forEach(x=>x.disabled=true);try{await fn();}catch(e){notice(friendly(e),true);}finally{busy=false;root.querySelectorAll('button,input,select').forEach(x=>x.disabled=false);}}
document.addEventListener('submit',event=>{const form=event.target;if(!form.dataset.form)return;event.preventDefault();const values=Object.fromEntries(new FormData(form));run(async()=>{switch(form.dataset.form){case 'auth':{values.email=String(values.email||'').trim();if(!validEmail(values.email)){notice(BAD_EMAIL(),true);return;}const result=mode==='signup'?await client.auth.signUp({email:values.email,password:values.password,options:{emailRedirectTo:redirect}}):await client.auth.signInWithPassword({email:values.email,password:values.password});if(result.error)throw result.error;if(mode==='signup'&&!result.data.session){form.reset();notice(T('Request accepted. Check your email for the confirmation link, then return here to sign in.','Demande acceptée. Consultez votre e-mail pour confirmer, puis revenez vous connecter.'));}else await load();break;}case 'profile':{if(values.venue){await rpc('save_profile',{p_name:values.displayName,p_birth_date:null,p_locale:values.locale,p_accept_rules:values.rules==='on',p_bio:null,p_avatar_path:null});lang=values.locale;await load();break;}const file=form.querySelector('#photo')?.files?.[0]||pendingPhoto;const path=file?await uploadPhoto(file):null;if(!path&&!profile?.avatar_path)throw new Error('photo_missing');if(values.interest&&values.interestConsent!=='on'){notice(T('Tick the consent box to use « Who would you like to see? », or leave it on « Everyone ».','Cochez la case de consentement pour utiliser « Qui souhaitez-vous voir ? », ou laissez « Tout le monde ».'),true);return;}await rpc('save_member_profile',{p_gender:values.gender||null,p_name:values.displayName,p_birth_date:values.birthDate,p_locale:values.locale,p_accept_rules:values.rules==='on',p_bio:values.bio,p_avatar_path:path});await rpc('set_interest',{p_interest:values.interest||null,p_consent:values.interestConsent==='on'});await rpc('set_height',{p_cm:values.height?Math.round(Number(values.height)):null});await rpc('set_department',{p_department:values.department||null});await removeOldPhoto(profile?.avatar_path,path);photoPreview='';pendingPhoto=null;lang=values.locale;await load();break;}case 'settings':{if(values.venue){await rpc('save_profile',{p_name:values.displayName,p_birth_date:null,p_locale:values.locale,p_accept_rules:true,p_bio:null,p_avatar_path:null});lang=values.locale;view='home';await load();notice(T('Saved.','Enregistré.'));break;}const file=form.querySelector('#photo')?.files?.[0];const path=file?await uploadPhoto(file):null;if(values.interest&&values.interestConsent!=='on'){notice(T('Tick the consent box to use « Who would you like to see? », or leave it on « Everyone ».','Cochez la case de consentement pour utiliser « Qui souhaitez-vous voir ? », ou laissez « Tout le monde ».'),true);return;}await rpc('save_member_profile',{p_gender:values.gender||null,p_name:values.displayName,p_birth_date:profile.birth_date,p_locale:values.locale,p_accept_rules:true,p_bio:values.bio,p_avatar_path:path});await rpc('set_interest',{p_interest:values.interest||null,p_consent:values.interestConsent==='on'});await rpc('set_height',{p_cm:values.height?Math.round(Number(values.height)):null});await rpc('set_department',{p_department:values.department||null});await removeOldPhoto(profile.avatar_path,path||profile.avatar_path);photoPreview='';lang=values.locale;view='home';await load();notice(T('Profile updated.','Profil mis à jour.'));break;}case 'intro':await rpc('send_introduction',{p_to:person.user_id,p_message:values.message});view='person';render();notice(T('Introduction sent. The other person decides whether to reply.','Présentation envoyée. L’autre personne décide de répondre ou non.'));break;case 'accept':{const r=await rpc('respond_introduction',{p_id:form.dataset.intro,p_accept:true,p_reply:values.reply});await openThread(r.conversation_id);break;}case 'message':{await rpc('send_message',{p_conversation:form.dataset.conversation,p_body:values.body});form.reset();await openThread(form.dataset.conversation,true);const b=document.querySelector('.thread');if(b)b.scrollTop=b.scrollHeight;break;}case 'report':{await rpc('report_member',{p_user:form.dataset.user,p_category:values.category,p_details:values.details||null,p_conversation:form.dataset.conversation||null});if(values.alsoBlock==='on')await rpc('block_member',{p_user:form.dataset.user});reportTarget=null;stopThread();thread=null;await loadInbox();notice(T('Thank you. Your report has been sent. This person can no longer write to you or introduce themselves to you.','Merci. Votre signalement a été envoyé. Cette personne ne peut plus vous écrire ni se présenter à vous.'));break;}case 'apply':await rpc('apply_venue',{p_name:values.name,p_category:values.category,p_address:values.address,p_hours:values.hours||null,p_contact:values.contact||null,p_duration:Number(values.duration)});await load();notice(T('Application sent. The team will review it.','Demande envoyée. L’équipe va l’examiner.'));break;case 'venue-invite':{const r=await rpc('venue_create_invite',{p_days:Number(values.days)});const url=new URL('./account.html?venue='+encodeURIComponent(r.token),redirect).href;venueQr[r.id]={url,qr:await qrDataUrl(url)};await load();notice(T('New QR code created. It is shown only once: download it now.','Nouveau QR code créé. Il n’est affiché qu’une fois : téléchargez-le maintenant.'));break;}case 'venue-announce':await rpc('venue_announce',{p_body:values.body});await load();break;case 'venue-update':await rpc('venue_update',{p_hours:values.hours||null,p_contact:values.contact||null,p_duration:Number(values.duration)});await load();notice(T('Saved.','Enregistré.'));break;case 'pro':{await rpc('save_pro_profile',{p_business:values.business,p_professional:values.professional||null,p_category:values.category,p_pitch:values.pitch,p_website:values.website||null,p_socials:{instagram:values.instagram||null,tiktok:values.tiktok||null,linkedin:values.linkedin||null},p_city:values.city||null});sessionStorage.removeItem('prorod-pro-later');view='pro';await load();notice(T('Sheet saved. The team reviews it before it is shown.','Fiche enregistrée. L’équipe la vérifie avant affichage.'));break;}case 'enquiry':await rpc('send_enquiry',{p_pro:form.dataset.user,p_message:values.message,p_contact:values.contact||null});view='talents';render();notice(T('Enquiry sent.','Demande envoyée.'));break;case 'feedback':{await rpc('submit_feedback',{p_score:Number(values.score),p_change:values.change||null,p_bug:values.bug==='on',p_bug_text:values.bugText||null,p_context:{lang,minutes:Math.round(usedMs()/60000),screen:typeof view==='string'?view:'accept',installed:matchMedia('(display-mode: standalone)').matches||navigator.standalone===true,ua:navigator.userAgent}});localStorage.setItem('prorod-feedback-done','1');document.getElementById('feedback-dialog')?.close();notice(T('Thank you! Your feedback has been sent to the test team.','Merci ! Votre avis a été envoyé à l’équipe du test.'));break;}case 'phone':{const {error}=await client.auth.signInWithOtp({phone:values.phone});if(error){error.smsStep=true;throw error;}phoneValue=values.phone;phoneStep='code';render();break;}case 'phone-code':{const {error}=await client.auth.verifyOtp({phone:phoneValue,token:values.code,type:'sms'});if(error)throw error;phoneStep=null;mode='signin';await load();break;}case 'link-phone':{const {error}=await client.auth.updateUser({phone:values.linkPhone});if(error){error.smsStep=true;throw error;}linkPhone=values.linkPhone;render();break;}case 'link-phone-code':{const {error}=await client.auth.verifyOtp({phone:linkPhone,token:values.linkCode,type:'phone_change'});if(error)throw error;linkPhone=null;await load();notice(T('Phone number added: you can now sign in with it too.','Numéro ajouté : vous pouvez aussi vous connecter avec.'));break;}case 'link-email':{const {error}=await client.auth.updateUser({email:values.linkEmail},{emailRedirectTo:redirect});if(error)throw error;notice(T('Check your inbox (and spam) to confirm this email.','Consultez votre boîte de réception (et les spams) pour confirmer cet e-mail.'));break;}case 'password':{const {error}=await client.auth.updateUser({password:values.password});if(error)throw error;recovery=false;await load();notice(T('Password updated.','Mot de passe mis à jour.'));break;}}});});
document.addEventListener('click',event=>{const target=event.target.closest('button');if(!target||busy)return;if(target.dataset.language){lang=target.dataset.language;render();return;}if(target.dataset.mode){mode=target.dataset.mode;phoneStep=null;notice('');render();window.scrollTo({top:0});return;}if(target.dataset.view){stopScan();stopThread();view=target.dataset.view;notice('');render();return;}if(target.dataset.person){person=people.find(m=>m.user_id===target.dataset.person)||null;if(person){view='person';render();}return;}if(target.dataset.talent){talent=talents.find(m=>m.user_id===target.dataset.talent)||null;if(talent){view='talent';render();}return;}if(target.dataset.type){run(async()=>{await rpc('set_account_type',{p_type:target.dataset.type});await load();});return;}if(target.dataset.action==='talents'){notice('');loadTalents().catch(e=>{view='home';render();notice(friendly(e),true);});return;}if(target.dataset.action==='feedback'){openFeedback(true);return;}if(target.dataset.action==='feedback-later'){snoozeFeedback();return;}if(target.dataset.action==='translate'){translateMessage(target.dataset.msg);return;}if(target.dataset.action==='translate-draft'){const box=document.querySelector('form[data-form="message"] textarea');if(!box||!box.value.trim())return;run(async()=>{const r=await translateText(box.value.trim(),lang==='fr'?'en':'fr');box.value=r.text;notice(T('Draft translated. Check it, then send.','Brouillon traduit. Relisez, puis envoyez.'));});return;}if(target.dataset.action==='skip-pro'){sessionStorage.setItem('prorod-pro-later','1');view='home';render();return;}if(target.dataset.conversation&&!target.dataset.action){notice('');openThread(target.dataset.conversation).catch(e=>{view='messages';render();notice(friendly(e),true);});return;}if(target.dataset.action==='messages'){notice('');stopScan();stopThread();thread=null;loadInbox().catch(e=>{view='home';render();notice(friendly(e),true);});return;}if(target.dataset.action==='accept'){view={name:'accept',id:target.dataset.intro};notice('');render();return;}if(target.dataset.action==='report'){reportTarget={user:target.dataset.user,conversation:target.dataset.conversation||null};view='report';notice('');render();return;}if(target.dataset.action==='people'){stopScan();stopThread();notice('');loadPeople().catch(e=>{view='home';render();notice(friendly(e),true);});return;}if(target.dataset.action==='scan'){notice('');startScan().catch(e=>{stopScan();view='home';render();notice(friendly(e),true);});return;}const action=target.dataset.action;if(!action)return;run(async()=>{if(action==='passkey-signin'){const {error}=await client.auth.signInWithPasskey();if(error){notice(passkeyMessage(error),true);return;}mode='signin';await load();}else if(action==='passkey-register'){const {error}=await client.auth.registerPasskey();if(error){notice(passkeyMessage(error),true);return;}await loadPasskeys();render();notice(T('Passkey added: next time, sign in with Face ID, fingerprint or PIN.','Clé d’accès ajoutée : la prochaine fois, connectez-vous avec Face ID, empreinte ou code.'));}else if(action==='passkey-later'){try{localStorage.setItem(passkeyLaterKey(),'1');}catch{}render();}else if(action==='passkey-delete'){if(!confirm(T('Remove this passkey?','Retirer cette clé d’accès ?')))return;const {error}=await client.auth.passkey.delete({passkeyId:target.dataset.id});if(error)throw error;await loadPasskeys();render();}else if(action==='google'){const {error}=await client.auth.signInWithOAuth({provider:'google',options:{redirectTo:redirect}});if(error)throw error;}else if(action==='buy-pass'){const r=await rpc('buy_pass_simulated');passes=await rpc('my_passes')||[];if(target.dataset.conversation){await openThread(target.dataset.conversation,true);}else if(view==='people'){await loadPeople();}else render();notice(r.already?T('You already have a pass for this place.','Vous avez déjà un pass pour ce lieu.'):T('Pass activated (simulation, nothing charged).','Pass activé (simulation, rien n’est débité).'));}else if(action==='subscribe'){await rpc('subscribe_talent_simulated');proData=await rpc('my_pro_profile');render();notice(T('Subscription activated (simulation).','Abonnement activé (simulation).'));}else if(action==='become-pro'){await rpc('set_account_type',{p_type:'pro'});sessionStorage.removeItem('prorod-pro-later');await load();}else if(action==='venue-revoke'){if(!confirm(T('Revoke this QR code? People checked in with it will be signed out of the place.','Révoquer ce QR code ? Les personnes entrées avec seront déconnectées du lieu.')))return;await rpc('venue_revoke_invite',{p_id:target.dataset.id});delete venueQr[target.dataset.id];await load();}else if(action==='venue-unannounce'){await rpc('venue_delete_announcement',{p_id:target.dataset.id});await load();}else if(action==='meet'){if(meetingTimer){clearInterval(meetingTimer);meetingTimer=null;}await rpc('meeting_answer',{p_conversation:target.dataset.conversation,p_yes:target.dataset.answer==='yes'});await openThread(target.dataset.conversation,true);}else if(action==='push-on'){await pushEnable();}else if(action==='push-off'){await pushDisable();}else if(action==='export'){const data=await rpc('my_data_export');const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`prod-mes-donnees-${new Date().toISOString().slice(0,10)}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),2000);notice(T('Your data file is ready.','Votre fichier de données est prêt.'));}else if(action==='decline'){await rpc('respond_introduction',{p_id:target.dataset.intro,p_accept:false});await loadInbox();}else if(action==='close'){endingConv=true;render();return;}else if(action==='close-cancel'){endingConv=false;render();return;}else if(action==='close-confirm'){const reason=root.querySelector('input[name="endReason"]:checked')?.value;if(!reason){notice(T('Choose a reason.','Choisissez une raison.'),true);return;}await rpc('end_conversation',{p_id:target.dataset.conversation,p_reason:reason});endingConv=false;await openThread(target.dataset.conversation,true);}else if(action==='block'){if(!confirm(T('Block this person? They will no longer see you or write to you, in any place.','Bloquer cette personne ? Elle ne vous verra plus et ne pourra plus vous écrire, dans aucun lieu.')))return;await rpc('block_member',{p_user:target.dataset.user});stopThread();thread=null;person=null;await loadInbox();notice(T('Person blocked.','Personne bloquée.'));}else if(action==='delete'){if(!confirm(T('Delete your account permanently?','Supprimer définitivement votre compte ?')))return;await pushDisable(true);await rpc('delete_account');await client.auth.signOut({scope:'local'}).catch(()=>{});user=profile=session=venue=null;invite='';view='home';sessionStorage.removeItem('prorod-invite');render();notice(T('Your account has been deleted.','Votre compte a été supprimé.'));}else if(action==='signout'){await pushDisable(true);linkPhone=null;pendingPhoto=null;passkeys=null;const {error}=await client.auth.signOut({scope:'local'});if(error)throw error;user=profile=session=venue=null;accountType=null;venueData=proData=room=null;passes=[];translations={};invite='';mode='landing';sessionStorage.removeItem('prorod-invite');render();}else if(action==='join'){session=await rpc('join_venue',{p_token:invite});venue=null;invite='';sessionStorage.removeItem('prorod-invite');try{room=await rpc('venue_room');}catch{room=null;}try{passes=await rpc('my_passes')||[];}catch{}render();}else if(action==='leave'){await rpc('leave_venue');session=null;people=[];person=null;talents=[];talent=null;room=null;view='home';render();}else{const email=document.getElementById('email');if(!email?.value||!email.checkValidity()){notice(T('Enter your email address first.','Saisissez d’abord votre adresse e-mail.'),true);return;}if(!validEmail(email.value)){notice(BAD_EMAIL(),true);return;}const addr=email.value.trim();const {error}=action==='resend'?await client.auth.resend({type:'signup',email:addr,options:{emailRedirectTo:redirect}}):await client.auth.resetPasswordForEmail(addr,{redirectTo:redirect});if(error)throw error;notice(T('Request accepted. If your account is eligible, check your email.','Demande acceptée. Si votre compte est éligible, consultez vos e-mails.'));}});});
document.addEventListener('change',event=>{const input=event.target;if(input.dataset?.toggle==='autotranslate'){autoTranslate=input.checked;localStorage.setItem('prorod-autotranslate',autoTranslate?'1':'0');if(autoTranslate)autoTranslateThread().catch(()=>{});return;}if(input.id==='photo'&&input.files?.[0]){pendingPhoto=input.files[0];if(photoPreview)URL.revokeObjectURL(photoPreview);photoPreview=URL.createObjectURL(input.files[0]);const img=input.parentElement.querySelector('.photo-preview');if(img&&img.tagName==='IMG')img.src=photoPreview;else if(img){const el=document.createElement('img');el.className='photo-preview';el.alt='';el.src=photoPreview;img.replaceWith(el);}}if(input.name==='birthDate'&&input.type==='date'){const hint=document.getElementById('age-hint');const a=age(input.value);if(hint&&a!==null)hint.textContent=(a>=18?T(`You are ${a}. `,`Vous avez ${a} ans. `):T(`You are ${a}: the pilot is for adults only. `,`Vous avez ${a} ans : le pilote est réservé aux adultes. `))+T('Other members see your age, never your birth date.','Les autres membres voient votre âge, jamais votre date de naissance.');}});
client.auth.onAuthStateChange(event=>{if(event==='PASSWORD_RECOVERY'){recovery=true;setTimeout(()=>load().catch(e=>notice(friendly(e),true)),0);}if(event==='SIGNED_OUT'){user=profile=session=venue=null;render();}});
setInterval(clock,1000);
load().catch(e=>{render();notice(friendly(e),true);});
if('serviceWorker' in navigator && window.isSecureContext)navigator.serviceWorker.register('./sw.js').catch(()=>{});
